FILES["app/control.lua"] = [[
-- Control-room computer: dispatcher + map server + monitor UI in one program.
--
-- Peripherals (any side): ender modem (required), advanced monitor (map),
-- optional: Player Detector, Chat Box (alerts to config.owner), speaker (chime).
-- The computer's own screen shows a console: log, rejected messages, key commands.

local P = require("lib.proto")
local U = require("lib.util")
local Net = require("lib.net")
local Log = require("lib.log")
local Up = require("lib.update")
local Fleet = require("server.fleet")
local Notify = require("server.notify")
local App = require("ui.app")

local function findMonitor(cfg)
  local side = cfg.monitor and cfg.monitor.side
  if side and peripheral.getType(side) == "monitor" then return peripheral.wrap(side), side end
  local best, bestSide
  for _, name in ipairs(peripheral.getNames()) do
    if peripheral.getType(name) == "monitor" then
      local m = peripheral.wrap(name)
      if m.isColor() and not best then best, bestSide = m, name end
    end
  end
  return best, bestSide
end

return function(cfg)
  local log = Log.new({ path = "/fleet/data/log.txt", keep = 60 })
  local dim = P.normDim(cfg.dim) or "overworld"
  local net = Net.new({ secret = cfg.secret, dim = dim, window = cfg.replayWindow })
  if not net:open() then error("The control computer needs an ender modem attached", 0) end

  local fleet = Fleet.new(cfg, log)
  fleet:load()
  local notify = Notify.new(cfg, log)
  fleet.onAlert = function(a) notify:alert(a) end
  fleet.onResolve = function(a, note) notify:resolved(a, note) end
  local upd = Up.server({ net = net, log = log })

  local source = {
    view = function(_, d) return fleet:view(d, os.epoch("utc")) end,
    action = function(_, a) return fleet:action(a) end,
  }

  local mon, monSide = findMonitor(cfg)
  local ui
  if mon then
    mon.setTextScale(cfg.monitor and cfg.monitor.scale or 0.5)
    ui = App.new({ term = mon, source = source, kind = "monitor", side = monSide, dim = dim,
      ascii = cfg.ui and cfg.ui.ascii })
    log:info("map on monitor '%s' (%dx%d)", monSide, mon.getSize())
  else
    log:warn("no advanced monitor found: map shown on this screen")
    ui = App.new({ term = term.current(), source = source, kind = "term", dim = dim,
      ascii = cfg.ui and cfg.ui.ascii })
  end

  local function netLoop()
    while true do
      local _, a, b, c = os.pullEvent("rednet_message")
      local from, body = net:unwrap(a, b, c)
      if from then
        if body.type == P.UPD_REQ then
          upd:handle(from, body)
        else
          local reply = fleet:handle(from, body, os.epoch("utc"))
          if reply then net:send(from, reply) end
        end
      end
    end
  end

  local function tickLoop()
    while true do
      local now = os.epoch("utc")
      fleet:tick(now)
      fleet:saveIfDue(now, 10)
      sleep(1)
    end
  end

  local function updateLoop()
    fleet.ver = upd:refresh().ver
    log:info("code version %s", fleet.ver)
    while true do
      upd:pump()
      sleep(0.5)
    end
  end

  local function console()
    if not mon then
      while true do os.pullEvent("fleet_never") end
    end
    local function draw()
      local w, h = term.getSize()
      term.setBackgroundColor(colors.black)
      term.clear()
      term.setCursorPos(1, 1)
      term.setTextColor(colors.yellow)
      term.write(U.trunc(("TurtleGPS control #%d  %s  code %s"):format(os.getComputerID(), P.dimLabel(dim), fleet.ver), w))
      term.setCursorPos(1, 2)
      term.setTextColor(colors.lightGray)
      local s = net.stats
      term.write(U.trunc(("msgs in %d  out %d  rejected %d  updates sent %d"):format(s.recv, s.sent, s.rejected, upd.served), w))
      local y = 3
      local r = s.last[1]
      if r then
        term.setCursorPos(1, y)
        term.setTextColor(colors.orange)
        term.write(U.trunc(("last rejected: #%d %s (%s ago)"):format(r.from, r.reason, U.age(os.epoch("utc") - r.t)), w))
        y = y + 1
      end
      local dn = fleet.denied[1]
      if dn then
        term.setCursorPos(1, y)
        term.setTextColor(colors.orange)
        term.write(U.trunc(("last denied: #%d %s: %s"):format(dn.from, dn.what, dn.why), w))
        y = y + 1
      end
      term.setCursorPos(1, y)
      term.setTextColor(colors.cyan)
      term.write(U.trunc("[U] push update to fleet  [S] save now  Ctrl+T stop", w))
      local lines = log.lines
      local room = h - y
      for i = math.max(1, #lines - room + 1), #lines do
        y = y + 1
        term.setCursorPos(1, y)
        local l = lines[i]
        term.setTextColor(l.level == "error" and colors.red or (l.level == "warn" and colors.orange or colors.white))
        term.write(U.trunc(l.text, w))
      end
    end
    local timer = os.startTimer(1)
    draw()
    while true do
      local ev, a = os.pullEvent()
      if ev == "timer" and a == timer then
        draw()
        timer = os.startTimer(1)
      elseif ev == "char" and (a == "u" or a == "U") then
        if upd:offer() then log:info("update %s offered to the fleet", fleet.ver) end
      elseif ev == "char" and (a == "s" or a == "S") then
        fleet:save()
        log:info("saved")
      end
    end
  end

  log:info("control #%d up in %s; commanders: %s", os.getComputerID(), dim,
    #(cfg.commanders or {}) > 0 and table.concat(cfg.commanders, ",") or "none")
  parallel.waitForAny(netLoop, tickLoop, updateLoop, function() ui:run() end, console,
    function() notify:pump() end)
end
]]
FILES["app/gpshost.lua"] = [[
-- GPS host: answers GPS pings like `gps host`, but also tells the asker which
-- dimension it is in ({ x, y, z, dim = ... }; stock gps.locate still accepts it).
--
-- On startup and every 5 minutes it pings the other hosts and compares the measured
-- distances with the configured coordinates, so a mistyped coordinate shows up on
-- this screen. It also sends a small heartbeat to the control computer.

local U = require("lib.util")
local P = require("lib.proto")
local Net = require("lib.net")
local Log = require("lib.log")
local Up = require("lib.update")
local locate = require("lib.locate")

local CH = locate.CHANNEL

return function(cfg)
  local log = Log.new({ path = "/fleet/data/log.txt" })
  local dim = P.normDim(cfg.dim)
  local me = { x = cfg.x, y = cfg.y, z = cfg.z }
  local modem, side = U.findWirelessModem()
  if not modem then error("GPS host needs an ender modem attached", 0) end
  modem.open(CH)

  local net = Net.new({ secret = cfg.secret, dim = dim, window = cfg.replayWindow, maxBody = 200000 })
  net:open()
  local updater = Up.client({ net = net, serverId = cfg.serverId, log = log })
  local stats = { served = 0, lastPing = nil, peers = nil, checkAt = nil, verdict = "checking...", ackAt = nil }

  local function serve()
    while true do
      local _, s, ch, reply, msg, dist = os.pullEvent("modem_message")
      if s == side and ch == CH and msg == "PING" and dist then
        modem.transmit(reply, CH, { me.x, me.y, me.z, dim = dim })
        stats.served = stats.served + 1
        stats.lastPing = os.epoch("utc")
      end
    end
  end

  local function selfCheck()
    modem.transmit(CH, CH, "PING")
    local peers, seen = {}, {}
    local timer = os.startTimer(2)
    while true do
      local ev, s, ch, _, msg, dist = os.pullEvent()
      if ev == "modem_message" and s == side and ch == CH and dist and type(msg) == "table"
          and tonumber(msg[1]) and tonumber(msg[2]) and tonumber(msg[3]) then
        local p = { x = tonumber(msg[1]), y = tonumber(msg[2]), z = tonumber(msg[3]) }
        local key = p.x .. "," .. p.y .. "," .. p.z
        if not seen[key] then
          seen[key] = true
          local expect = math.sqrt((p.x - me.x) ^ 2 + (p.y - me.y) ^ 2 + (p.z - me.z) ^ 2)
          peers[#peers + 1] = { p = p, d = dist, expect = expect, ok = math.abs(expect - dist) < 0.5,
            dim = P.normDim(msg.dim) }
        end
      elseif ev == "timer" and s == timer then
        break
      end
    end
    stats.peers, stats.checkAt = peers, os.epoch("utc")
    local bad, points, close = 0, { me }, 0
    for _, pr in ipairs(peers) do
      if not pr.ok then bad = bad + 1 end
      if pr.d < 6 then close = close + 1 end
      points[#points + 1] = pr.p
    end
    if #peers == 0 then
      stats.verdict = "no other hosts heard (need 4 in this dimension)"
    elseif bad > 0 and bad == #peers and #peers >= 2 then
      stats.verdict = "MY coordinates look wrong (all peers disagree)"
    elseif bad > 0 then
      stats.verdict = bad .. " peer(s) disagree: check their coordinates"
    elseif #points < 4 then
      stats.verdict = (#points) .. " hosts total: need at least 4"
    elseif locate.spread(points) < 1e-3 then
      stats.verdict = "hosts are (nearly) coplanar: raise or lower one"
    elseif close > 0 then
      stats.verdict = "OK, but keep hosts 6+ blocks apart for stock gps"
    else
      stats.verdict = "OK: " .. #points .. " hosts, good 3D spread"
    end
    log:info("self-check: %s", stats.verdict)
  end

  local function checker()
    sleep(1 + math.random() * 2)
    while true do
      selfCheck()
      sleep(300)
    end
  end

  local function heartbeat()
    while true do
      net:send(cfg.serverId, {
        type = P.HB, role = "gpshost", label = os.getComputerLabel(), x = me.x, y = me.y, z = me.z,
        served = stats.served, verdict = stats.verdict, ver = updater.ver,
      })
      sleep(20)
      updater:tick()
    end
  end

  local function netLoop()
    while true do
      local ev, a, b, c = os.pullEvent("rednet_message")
      local from, body = net:unwrap(a, b, c)
      if from == cfg.serverId then
        if body.type == P.HB_ACK then
          stats.ackAt = os.epoch("utc")
          updater:serverVersion(body.ver)
        else
          updater:handle(from, body)
        end
      end
    end
  end

  local function screen()
    while true do
      local now = os.epoch("utc")
      term.setBackgroundColor(colors.black)
      term.clear()
      term.setCursorPos(1, 1)
      term.setTextColor(colors.yellow)
      print("TurtleGPS GPS host #" .. os.getComputerID() .. "  " .. updater.ver)
      term.setTextColor(colors.white)
      print("Dimension: " .. P.dimLabel(dim))
      print("Position:  " .. U.fmtPos(me))
      print("Served:    " .. stats.served .. " pings" ..
        (stats.lastPing and (" (last " .. U.age(now - stats.lastPing) .. " ago)") or ""))
      print("Server:    " .. (stats.ackAt and ("OK " .. U.age(now - stats.ackAt) .. " ago") or "no reply yet"))
      print("")
      term.setTextColor(stats.verdict:find("^OK") and colors.lime or colors.orange)
      print("Check: " .. stats.verdict)
      term.setTextColor(colors.lightGray)
      for i, pr in ipairs(stats.peers or {}) do
        if i > 8 then break end
        local line = string.format(" %-18s d=%7.2f %s", U.fmtPos(pr.p), pr.d,
          pr.ok and "ok" or string.format("EXPECTED %.2f", pr.expect))
        term.setTextColor(pr.ok and colors.lightGray or colors.red)
        print(line)
      end
      if updater.status then
        term.setTextColor(colors.cyan)
        print(updater.status)
      end
      term.setTextColor(colors.white)
      sleep(2)
    end
  end

  log:info("GPS host up at %s in %s", U.fmtPos(me), dim)
  parallel.waitForAny(serve, checker, heartbeat, netLoop, screen)
end
]]
FILES["app/pocket.lua"] = [[
-- Pocket app placeholder until milestone 2. It already checks in with the control
-- computer so it picks up the real pocket map by over-the-air update.

local P = require("lib.proto")
local Net = require("lib.net")
local Log = require("lib.log")
local Up = require("lib.update")

return function(cfg)
  local log = Log.new({ path = "/fleet/data/log.txt" })
  local net = Net.new({ secret = cfg.secret, dim = "unknown", window = cfg.replayWindow, maxBody = 200000 })
  net:open()
  local updater = Up.client({ net = net, serverId = cfg.serverId, log = log })
  local ackAt

  local function draw()
    term.setBackgroundColor(colors.black)
    term.clear()
    term.setCursorPos(1, 1)
    term.setTextColor(colors.yellow)
    print("TurtleGPS pocket #" .. os.getComputerID())
    term.setTextColor(colors.white)
    print("")
    print("The pocket map arrives in")
    print("milestone 2. This pocket")
    print("updates itself from the")
    print("control computer.")
    print("")
    print("Control #" .. cfg.serverId .. ": " .. (ackAt and "OK" or "no reply yet"))
    print("Code: " .. updater.ver)
    if updater.status then print(updater.status) end
  end

  parallel.waitForAny(function()
    while true do
      net:send(cfg.serverId, { type = P.HB, role = "pocket", ver = updater.ver })
      updater:tick()
      draw()
      sleep(10)
    end
  end, function()
    while true do
      local _, a, b, c = os.pullEvent("rednet_message")
      local from, body = net:unwrap(a, b, c)
      if from == cfg.serverId then
        if body.type == P.HB_ACK then
          ackAt = os.epoch("utc")
          updater:serverVersion(body.ver)
        else
          updater:handle(from, body)
        end
      end
    end
  end)
end
]]
FILES["app/turtle.lua"] = [[
-- Turtle agent: finds its position and heading, then heartbeats telemetry to the
-- control computer every few seconds. Only messages signed with the fleet secret AND
-- sent by the configured control computer are obeyed.
--
-- Hardware: Chunky Turtle upgrade on one side, ender modem on the other.
-- Slot 16 is reserved for the swap tool (diamond pickaxe) used by later milestones.

local P = require("lib.proto")
local U = require("lib.util")
local Net = require("lib.net")
local Log = require("lib.log")
local Up = require("lib.update")
local Nav = require("turtle.nav")

return function(cfg)
  local log = Log.new({ path = "/fleet/data/log.txt" })
  local nav = Nav.new({ log = log, dim = cfg.dim })
  nav:load()

  local state = {
    status = "booting", job = nil, msg = nil,
    ackAt = nil, sentAt = nil, serverVer = nil,
  }
  local net = Net.new({
    secret = cfg.secret, dim = function() return nav.dim end,
    window = cfg.replayWindow, maxBody = 200000,
  })
  net:open()
  local updater = Up.client({
    net = net, serverId = cfg.serverId, log = log,
    canApply = function() return state.status == "idle" end,
  })

  local reserved = {}
  for _, s in ipairs(cfg.reservedSlots or {}) do reserved[s] = true end

  local function inventory()
    local used, total = 0, 0
    for s = 1, 16 do
      if not reserved[s] then
        total = total + 1
        if turtle.getItemCount(s) > 0 then used = used + 1 end
      end
    end
    return used, total
  end

  local function fuel()
    local f = turtle.getFuelLevel()
    if f == "unlimited" then return -1, -1 end
    return f, turtle.getFuelLimit()
  end

  local function heartbeat()
    local t = nav:telemetry()
    local f, fmax = fuel()
    local used, total = inventory()
    return {
      type = P.HB, role = "turtle", label = os.getComputerLabel(), dim = t.dim,
      x = t.x, y = t.y, z = t.z, h = t.h, fix = t.fix, fixAge = t.fixAge, gpsErr = t.gpsErr,
      fuel = f, fuelMax = fmax, reserve = cfg.lowFuel,
      inv = { used, total },
      status = state.status, job = state.job, msg = state.msg,
      ver = updater.ver, up = math.floor(os.clock()),
    }
  end

  local function hbLoop()
    while true do
      if net:send(cfg.serverId, heartbeat()) then state.sentAt = os.epoch("utc") end
      sleep(cfg.heartbeat)
    end
  end

  local function netLoop()
    while true do
      local ev, a, b, c = os.pullEvent()
      if ev == "rednet_message" then
        local from, body = net:unwrap(a, b, c)
        if from == cfg.serverId then
          if body.type == P.HB_ACK then
            state.ackAt = os.epoch("utc")
            state.serverVer = body.ver
            updater:serverVersion(body.ver)
          else
            updater:handle(from, body)
          end
        elseif from then
          log:warn("ignored %s from #%d: only #%d may command this turtle", body.type, from, cfg.serverId)
        end
      elseif ev == "peripheral" or ev == "peripheral_detach" then
        net:open()
      end
    end
  end

  local function mainLoop()
    state.status = "locating"
    local ok, why = nav:calibrate()
    if ok then
      log:info("at %s facing %s (%s)", U.fmtPos(nav), P.HEADING_NAME[nav.h], why)
      state.msg = nil
    else
      log:warn("calibrate: %s", why)
      state.msg = why
    end
    state.status = "idle"
    local lastCal = os.epoch("utc")
    while true do
      sleep(2)
      updater:tick()
      local now = os.epoch("utc")
      if not nav.h or not nav:known() then
        if now - lastCal > 30000 then
          lastCal = now
          ok, why = nav:calibrate()
          state.msg = (not ok) and why or nil
        end
      elseif not nav.fixAt or now - nav.fixAt > cfg.gpsEvery * 1000 then
        nav:fix()
      end
    end
  end

  local function line(y, label, value, col)
    term.setCursorPos(1, y)
    term.setTextColor(colors.lightGray)
    term.write(U.pad(label, 8))
    term.setTextColor(col or colors.white)
    term.write(tostring(value))
  end

  local function screen()
    while true do
      local now = os.epoch("utc")
      local t = nav:telemetry()
      local f, fmax = fuel()
      local used, total = inventory()
      term.setBackgroundColor(colors.black)
      term.clear()
      term.setCursorPos(1, 1)
      term.setTextColor(colors.yellow)
      term.write(U.trunc("#" .. os.getComputerID() .. " " .. (os.getComputerLabel() or "turtle") .. "  " .. updater.ver, 39))
      line(2, "Dim", P.dimLabel(t.dim))
      line(3, "Status", state.status, state.status == "idle" and colors.lime or colors.white)
      line(4, "Pos", t.x and U.fmtPos(t) or "unknown", t.x and colors.white or colors.red)
      line(5, "Facing", t.h and P.HEADING_NAME[t.h] or "unknown", t.h and colors.white or colors.red)
      local fixText = t.fix == "none" and ("none: " .. tostring(t.gpsErr or "?"))
        or (t.fix .. (t.fixAge and (" (gps " .. U.age(t.fixAge * 1000) .. " ago)") or ""))
      line(6, "Fix", fixText, t.fix == "none" and colors.red or colors.white)
      line(7, "Fuel", f < 0 and "unlimited" or (f .. " / " .. fmax), (f >= 0 and f < cfg.lowFuel) and colors.orange or colors.white)
      line(8, "Inv", used .. " / " .. total .. " slots", used >= total and colors.orange or colors.white)
      local link, lc
      if not net:isUp() then link, lc = "NO MODEM", colors.red
      elseif state.ackAt and now - state.ackAt < (cfg.heartbeat * 3 + 2) * 1000 then
        link, lc = "OK (#" .. cfg.serverId .. ")", colors.lime
      elseif state.ackAt then
        link, lc = "no reply for " .. U.age(now - state.ackAt), colors.orange
      else
        link, lc = "no reply: check serverId/secret", colors.red
      end
      line(9, "Server", link, lc)
      if state.msg then line(10, "Note", U.trunc(state.msg, 31), colors.orange) end
      if updater.status then line(11, "Update", U.trunc(updater.status, 31), colors.cyan) end
      local last = log.lines[#log.lines]
      if last then
        term.setCursorPos(1, 13)
        term.setTextColor(colors.gray)
        term.write(U.trunc(last.text, 39))
      end
      sleep(1)
    end
  end

  log:info("turtle agent starting, server #%d", cfg.serverId)
  parallel.waitForAny(hbLoop, netLoop, mainLoop, screen)
end
]]
FILES["bin/gpscheck.lua"] = [[
-- gpscheck: run on any computer, turtle or pocket with an ender modem.
-- Lists every GPS host that answers in this dimension, solves the position, and
-- explains what is wrong if it cannot.

package.path = "/fleet/?.lua;" .. package.path
local locate = require("lib.locate")
local P = require("lib.proto")
local U = require("lib.util")

local function color(c) if term.isColor() then term.setTextColor(c) end end

if not U.findWirelessModem() then
  color(colors.red)
  print("No wireless/ender modem attached.")
  return
end

print("Pinging GPS hosts for 3 seconds...")
local pos, err, fixes = locate.locate(3, { all = true })
fixes = pos and pos.fixes or fixes or {}

color(colors.yellow)
print(("Heard %d host(s):"):format(#fixes))
for _, f in ipairs(fixes) do
  color(f.res and f.res > 0.5 and colors.red or colors.white)
  print(("  %-20s d=%8.2f %s%s"):format(U.fmtPos(f.p), f.d, f.dim and P.dimLabel(f.dim) or "(stock host)",
    f.res and f.res > 0.5 and ("  off by " .. ("%.1f"):format(f.res)) or ""))
end

if not pos then
  color(colors.red)
  print("No fix: " .. tostring(err))
  color(colors.white)
  if #fixes < 4 then
    print("Need 4 hosts in THIS dimension, in loaded chunks, each with an ender modem running gpshost.")
  end
  return
end

color(colors.lime)
print(("Position: %d, %d, %d  (%s)"):format(pos.bx, pos.by, pos.bz, pos.dim and P.dimLabel(pos.dim) or "dimension unknown"))
color(colors.white)
print(("Raw: %.2f, %.2f, %.2f  residual %.3f"):format(pos.x, pos.y, pos.z, pos.res))
if pos.dropped then
  color(colors.orange)
  print("Ignored inconsistent host at " .. U.fmtPos(pos.dropped.p))
end
if pos.res > 0.5 then
  color(colors.orange)
  print("Residual is high: a host's configured coordinates are probably wrong.")
end
if pos.cond < 0.01 then
  color(colors.orange)
  print("Hosts are nearly coplanar: move one host up or down for accuracy.")
end
color(colors.white)
]]
FILES["bin/setup.lua"] = [[
-- TurtleGPS setup: writes /fleet/config.lua and /startup.lua, then reboots.
-- Run again any time to change settings:  /fleet/bin/setup

package.path = "/fleet/?.lua;" .. package.path
local config = require("lib.config")
local P = require("lib.proto")

local function color(c) if term.isColor() then term.setTextColor(c) end end

local function ask(prompt, default)
  color(colors.yellow)
  write(prompt)
  if default ~= nil and default ~= "" then
    color(colors.lightGray)
    write(" [" .. tostring(default) .. "]")
  end
  color(colors.white)
  write(": ")
  local s = read()
  s = s and s:gsub("^%s+", ""):gsub("%s+$", "") or ""
  if s == "" then return default end
  return s
end

local function askNumber(prompt, default)
  while true do
    local s = ask(prompt, default)
    local n = tonumber(s)
    if n then return n end
    color(colors.red)
    print("Please enter a number.")
  end
end

local function genSecret()
  math.randomseed(os.epoch("utc") + os.getComputerID() * 7919)
  local chars = "abcdefghjkmnpqrstuvwxyz23456789"
  local out = {}
  for i = 1, 20 do
    local k = math.random(1, #chars)
    out[i] = chars:sub(k, k)
  end
  return table.concat(out)
end

term.clear()
term.setCursorPos(1, 1)
color(colors.lime)
print("TurtleGPS setup  -  this is computer #" .. os.getComputerID())
color(colors.white)

local old = config.load() or {}
local kind = turtle and "turtle" or (pocket and "pocket" or "computer")
local defaultRole = old.role or (kind == "turtle" and "turtle" or (kind == "pocket" and "pocket" or nil))
local role
repeat
  role = ask("Role (control, turtle, pocket, gpshost)", defaultRole)
until role == "control" or role == "turtle" or role == "pocket" or role == "gpshost"

local cfg = { role = role }

if role == "control" then
  local secret = ask("Shared secret (blank = generate)", old.secret)
  if not secret or #secret < 8 then
    secret = genSecret()
    color(colors.lime)
    print("Generated secret (type it on every fleet computer):")
    print("  " .. secret)
    color(colors.white)
  end
  cfg.secret = secret
else
  local secret
  repeat
    secret = ask("Shared secret (same as control)", old.secret)
    if not secret or #secret < 8 then color(colors.red); print("At least 8 characters.") end
  until secret and #secret >= 8
  cfg.secret = secret
  cfg.serverId = askNumber("Control computer ID", old.serverId)
end

if role == "control" or role == "gpshost" then
  local d
  repeat
    d = P.normDim(ask("Dimension of this computer (overworld, nether, end)", old.dim or "overworld"))
  until d
  cfg.dim = d
elseif role == "turtle" then
  local d = ask("Dimension (overworld, nether, end; blank = from GPS)", old.dim or "")
  cfg.dim = P.normDim(d)
end

if role == "gpshost" then
  print("Enter THIS computer's block coordinates (F3, look at it: 'Targeted Block').")
  cfg.x = askNumber("x", old.x)
  cfg.y = askNumber("y", old.y)
  cfg.z = askNumber("z", old.z)
end

if role == "control" then
  cfg.owner = ask("Your player name (for Chat Box alerts)", old.owner)
  local ids = ask("Pocket computer IDs allowed to command (comma separated)",
    old.commanders and table.concat(old.commanders, ",") or "")
  cfg.commanders = {}
  for n in tostring(ids or ""):gmatch("%d+") do cfg.commanders[#cfg.commanders + 1] = tonumber(n) end
  cfg.garages = old.garages
  cfg.monitor = old.monitor
end

if role == "pocket" then
  cfg.owner = ask("Your player name", old.owner)
end

if role == "turtle" or role == "pocket" then
  local label = ask("Label", os.getComputerLabel() or old.label or (role .. os.getComputerID()))
  if label then
    cfg.label = label
    os.setComputerLabel(label)
  end
end

local problems = config.problems(cfg)
if #problems > 0 then
  color(colors.red)
  for _, p in ipairs(problems) do print(p) end
  return
end

if not fs.exists("/fleet/data") then fs.makeDir("/fleet/data") end
config.save(cfg)
local startup = 'shell.run("/fleet/boot.lua")\n'
if fs.exists("/startup.lua") then
  local h = fs.open("/startup.lua", "r")
  local cur = h.readAll()
  h.close()
  if cur ~= startup then
    if fs.exists("/startup.lua.bak") then fs.delete("/startup.lua.bak") end
    fs.move("/startup.lua", "/startup.lua.bak")
    print("Old /startup.lua saved as /startup.lua.bak")
  end
end
local h = fs.open("/startup.lua", "w")
h.write(startup)
h.close()

color(colors.lime)
print("Saved /fleet/config.lua")
color(colors.white)
if role == "control" then
  print("Add garages and other options with: edit /fleet/config.lua")
end
local again = ask("Reboot now? (y/n)", "y")
if again == "y" or again == "Y" then os.reboot() end
]]
FILES["boot.lua"] = [[
-- TurtleGPS launcher, started by /startup.lua.
-- Runs this computer's role program and restarts it after a crash. If freshly updated
-- code crashes 3 times before running for a minute, the previous code is restored.
-- Hold Ctrl+T to stop and get a shell.

package.path = "/fleet/?.lua;/fleet/?/init.lua;" .. package.path

local config = require("lib.config")
local store = require("lib.store")
local Up = require("lib.update")

local APPS = { control = "app.control", turtle = "app.turtle", pocket = "app.pocket", gpshost = "app.gpshost" }

local function fail(lines)
  if term.isColor() then term.setTextColor(colors.red) end
  for _, l in ipairs(lines) do print(l) end
  term.setTextColor(colors.white)
  print("Run /fleet/bin/setup  or  edit /fleet/config.lua")
end

local cfg, err = config.load()
if not cfg then
  fail({ "TurtleGPS: cannot read /fleet/config.lua", tostring(err) })
  return
end
local problems = config.problems(cfg)
if #problems > 0 then
  fail(problems)
  return
end
if cfg.label and not os.getComputerLabel() then os.setComputerLabel(cfg.label) end

local function crashLog(msg)
  pcall(function()
    local h = fs.open("/fleet/data/crash.txt", "a")
    h.writeLine(os.epoch("utc") .. " " .. tostring(msg))
    h.close()
  end)
end

local crashes = 0
while true do
  local ok, perr
  local loaded, main = pcall(require, APPS[cfg.role])
  if not loaded then
    ok, perr = false, main
  else
    parallel.waitForAny(function()
      ok, perr = xpcall(function() main(cfg) end, debug.traceback)
    end, function()
      -- after a minute of running, new code counts as good
      sleep(60)
      local st = store.load(Up.STATE, {})
      if st.pending then
        st.pending, st.crashes = false, 0
        store.save(Up.STATE, st)
      end
      crashes = 0
      os.pullEvent("fleet_never")
    end)
  end
  if ok then return end
  if tostring(perr):find("Terminated", 1, true) then
    print("TurtleGPS stopped.")
    return
  end

  term.setCursorPos(1, 1)
  term.clear()
  if term.isColor() then term.setTextColor(colors.red) end
  print("TurtleGPS crashed:")
  print(tostring(perr))
  term.setTextColor(colors.white)
  crashLog(perr)

  local st = store.load(Up.STATE, {})
  if st.pending then
    st.crashes = (st.crashes or 0) + 1
    store.save(Up.STATE, st)
    if st.crashes >= 3 and Up.rollback() then
      print("New code keeps crashing: rolled back. Rebooting.")
      crashLog("rolled back update " .. tostring(st.ver))
      sleep(2)
      os.reboot()
    end
  end
  crashes = crashes + 1
  local delay = math.min(60, 5 * crashes)
  print("Restarting in " .. delay .. "s (hold Ctrl+T to stop)")
  sleep(delay)
  for name in pairs(package.loaded) do
    if name:match("^app%.") then package.loaded[name] = nil end
  end
end
]]
FILES["lib/config.lua"] = [[
-- Loads /fleet/config.lua (a Lua file returning a table) and fills in defaults per role.
-- Edit it in-game with:  edit /fleet/config.lua

local U = require("lib.util")

local C = {}
C.PATH = "/fleet/config.lua"
C.DATA = "/fleet/data"

C.DEFAULTS = {
  all = {
    role = nil,          -- "control" | "turtle" | "pocket" | "gpshost"
    secret = nil,        -- shared secret, identical on every fleet computer
    serverId = nil,      -- computer ID of the control-room computer
    dim = nil,           -- this computer's dimension (turtles/gps hosts/control)
    replayWindow = 30,   -- seconds a signed message stays valid
  },
  turtle = {
    heartbeat = 3,       -- seconds between heartbeats
    gpsEvery = 60,       -- seconds between GPS re-fixes while idle
    reservedSlots = { 16 }, -- slot 16 holds the swap tool (pickaxe <-> modem)
    lowFuel = 500,       -- report low fuel below this (plus distance home)
  },
  control = {
    dim = "overworld",
    commanders = {},     -- computer IDs allowed to send commands (pockets, extra UIs)
    turtles = nil,       -- optional allowlist of turtle IDs; nil = any computer with the secret
    staleAfter = 12,     -- seconds without heartbeat before a turtle is shown stale
    lostAfter = 45,      -- seconds without heartbeat before a turtle is LOST (alert)
    lowFuel = 500,
    owner = nil,         -- player name for Chat Box alerts
    monitor = { side = nil, scale = 0.5 },
    garages = {},        -- [dim] = { x = , y = , z = }  shown on the map
    ui = { ascii = false },
  },
  pocket = {
    owner = nil,         -- your player name (matches Player Detector results)
    refresh = 2,
    ui = { ascii = false },
  },
  gpshost = {
    x = nil, y = nil, z = nil,
  },
}

local function readConfigFile(path)
  if not fs.exists(path) then return nil, "missing" end
  local h = fs.open(path, "r")
  local src = h.readAll()
  h.close()
  local fn, err = load(src, "=config", "t", {})
  if not fn then return nil, err end
  local ok, t = pcall(fn)
  if not ok then return nil, t end
  if type(t) ~= "table" then return nil, "config.lua must return a table" end
  return t
end

--- Returns config table (with defaults) or nil plus an error.
function C.load(path)
  local t, err = readConfigFile(path or C.PATH)
  if not t then return nil, err end
  U.merge(t, C.DEFAULTS.all)
  if t.role and C.DEFAULTS[t.role] then U.merge(t, C.DEFAULTS[t.role]) end
  return t
end

--- Lists human readable problems with a config.
function C.problems(cfg)
  local p = {}
  local roles = { control = true, turtle = true, pocket = true, gpshost = true }
  if not roles[cfg.role] then p[#p + 1] = "role must be control, turtle, pocket or gpshost" end
  if type(cfg.secret) ~= "string" or #cfg.secret < 8 then
    p[#p + 1] = "secret must be at least 8 characters"
  end
  if cfg.role ~= "control" and type(cfg.serverId) ~= "number" then
    p[#p + 1] = "serverId must be the control computer's ID"
  end
  if cfg.role == "gpshost" then
    if type(cfg.x) ~= "number" or type(cfg.y) ~= "number" or type(cfg.z) ~= "number" then
      p[#p + 1] = "gpshost needs x, y, z of this computer"
    end
    if not cfg.dim then p[#p + 1] = "gpshost needs dim" end
  end
  return p
end

-- Readable Lua output so the file stays hand-editable.
local function pretty(v, indent)
  local t = type(v)
  if t == "string" then return string.format("%q", v) end
  if t ~= "table" then return tostring(v) end
  local pad = string.rep("  ", indent + 1)
  local parts = {}
  local n = #v
  for i = 1, n do parts[#parts + 1] = pad .. pretty(v[i], indent + 1) end
  for _, k in ipairs(U.sortedKeys(v)) do
    if not (type(k) == "number" and k >= 1 and k <= n) then
      local key = (type(k) == "string" and k:match("^[%a_][%w_]*$")) and k or ("[" .. pretty(k, 0) .. "]")
      parts[#parts + 1] = pad .. key .. " = " .. pretty(v[k], indent + 1)
    end
  end
  if #parts == 0 then return "{}" end
  return "{\n" .. table.concat(parts, ",\n") .. ",\n" .. string.rep("  ", indent) .. "}"
end

function C.save(cfg, path)
  path = path or C.PATH
  local keep = {}
  local defaults = C.DEFAULTS[cfg.role] or {}
  for k, v in pairs(cfg) do
    -- only write keys that differ from defaults, so new defaults reach old installs
    local d = defaults[k]
    if d == nil then d = C.DEFAULTS.all[k] end
    if type(v) == "table" or v ~= d then keep[k] = v end
  end
  local h = fs.open(path, "w")
  h.write("-- TurtleGPS fleet config. Same secret on every fleet computer.\n")
  h.write("return " .. pretty(keep, 0) .. "\n")
  h.close()
end

C.pretty = pretty

return C
]]
FILES["lib/locate.lua"] = [[
-- Dimension-aware GPS.
--
-- Our GPS hosts answer pings with { x, y, z, dim = "the_nether" }. Stock gps.locate still
-- accepts that (it only checks #msg == 3), and this locator also learns the dimension.
-- Ender modems deliver cross-dimension messages WITHOUT a distance, so only hosts in our
-- own dimension can contribute a fix.
--
-- Position is solved by least squares over all hosts heard, which also yields a residual
-- that exposes a host with mistyped coordinates.

local U = require("lib.util")
local P = require("lib.proto")

local L = {}
L.CHANNEL = 65534 -- same channel as the built-in gps API

--- fixes: list of { p = {x,y,z}, d = distance }. Returns pos {x,y,z,res,cond} or nil, reason.
function L.solve(fixes)
  local n = #fixes
  if n < 4 then return nil, "need 4 GPS hosts, heard " .. n end
  local p1, d1 = fixes[1].p, fixes[1].d
  local a11, a12, a13, a22, a23, a33 = 0, 0, 0, 0, 0, 0
  local r1, r2, r3 = 0, 0, 0
  for i = 2, n do
    local f = fixes[i]
    local qx, qy, qz = f.p.x - p1.x, f.p.y - p1.y, f.p.z - p1.z
    local c = 0.5 * (qx * qx + qy * qy + qz * qz - f.d * f.d + d1 * d1)
    a11, a12, a13 = a11 + qx * qx, a12 + qx * qy, a13 + qx * qz
    a22, a23, a33 = a22 + qy * qy, a23 + qy * qz, a33 + qz * qz
    r1, r2, r3 = r1 + qx * c, r2 + qy * c, r3 + qz * c
  end
  local det = a11 * (a22 * a33 - a23 * a23) - a12 * (a12 * a33 - a23 * a13) + a13 * (a12 * a23 - a22 * a13)
  local tr = (a11 + a22 + a33) / 3
  local cond = tr > 0 and math.abs(det) / (tr * tr * tr) or 0
  if cond < 1e-6 then return nil, "GPS hosts are coplanar (move one up or down)" end
  local x = (r1 * (a22 * a33 - a23 * a23) - a12 * (r2 * a33 - a23 * r3) + a13 * (r2 * a23 - a22 * r3)) / det
  local y = (a11 * (r2 * a33 - a23 * r3) - r1 * (a12 * a33 - a23 * a13) + a13 * (a12 * r3 - r2 * a13)) / det
  local z = (a11 * (a22 * r3 - r2 * a23) - a12 * (a12 * r3 - r2 * a13) + r1 * (a12 * a23 - a22 * a13)) / det
  local pos = { x = p1.x + x, y = p1.y + y, z = p1.z + z, cond = cond }
  local res = 0
  for i = 1, n do
    local f = fixes[i]
    local dx, dy, dz = pos.x - f.p.x, pos.y - f.p.y, pos.z - f.p.z
    local r = math.abs(math.sqrt(dx * dx + dy * dy + dz * dz) - f.d)
    f.res = r
    if r > res then res = r end
  end
  pos.res = res
  return pos
end

--- Solves, and if the result is inconsistent and there are spare hosts, drops the
--- host that disagrees (e.g. a stranger's misconfigured GPS host).
function L.robustSolve(fixes)
  local pos, err = L.solve(fixes)
  if not pos or pos.res <= 0.5 or #fixes < 5 then return pos, err end
  local best
  for skip = 1, #fixes do
    local sub = {}
    for i, f in ipairs(fixes) do if i ~= skip then sub[#sub + 1] = f end end
    local p = L.solve(sub)
    if p and (not best or p.res < best.res) then
      best = p
      best.dropped = fixes[skip]
    end
  end
  if best and best.res < pos.res then return best end
  return pos
end

--- How three-dimensional a set of host positions is: 0 = coplanar, ~1 = well spread.
function L.spread(points)
  if #points < 4 then return 0 end
  local p1 = points[1]
  local a11, a12, a13, a22, a23, a33 = 0, 0, 0, 0, 0, 0
  for i = 2, #points do
    local qx, qy, qz = points[i].x - p1.x, points[i].y - p1.y, points[i].z - p1.z
    a11, a12, a13 = a11 + qx * qx, a12 + qx * qy, a13 + qx * qz
    a22, a23, a33 = a22 + qy * qy, a23 + qy * qz, a33 + qz * qz
  end
  local det = a11 * (a22 * a33 - a23 * a23) - a12 * (a12 * a33 - a23 * a13) + a13 * (a12 * a23 - a22 * a13)
  local tr = (a11 + a22 + a33) / 3
  if tr <= 0 then return 0 end
  return math.abs(det) / (tr * tr * tr)
end

local function majorityDim(fixes)
  local count, best, bestN = {}, nil, 0
  for _, f in ipairs(fixes) do
    if f.dim then
      count[f.dim] = (count[f.dim] or 0) + 1
      if count[f.dim] > bestN then best, bestN = f.dim, count[f.dim] end
    end
  end
  return best
end

--- Pings GPS hosts. opts.all = wait the full timeout and return every host heard.
--- Returns pos { x, y, z (floats), bx, by, bz (block coords), dim, n, res, fixes } or nil, reason.
function L.locate(timeout, opts)
  opts = opts or {}
  local modem, side = U.findWirelessModem()
  if not modem then return nil, "no wireless modem" end
  local wasOpen = modem.isOpen(L.CHANNEL)
  if not wasOpen then modem.open(L.CHANNEL) end
  modem.transmit(L.CHANNEL, L.CHANNEL, "PING")

  local fixes, seen = {}, {}
  local timer = os.startTimer(timeout or 2)
  local pos
  while true do
    local ev, a, b, c, d, e = os.pullEvent()
    if ev == "modem_message" then
      if a == side and b == L.CHANNEL and c == L.CHANNEL and e and type(d) == "table"
          and tonumber(d[1]) and tonumber(d[2]) and tonumber(d[3]) then
        local key = d[1] .. "," .. d[2] .. "," .. d[3]
        if not seen[key] then
          seen[key] = true
          fixes[#fixes + 1] = {
            p = { x = tonumber(d[1]), y = tonumber(d[2]), z = tonumber(d[3]) },
            d = e, dim = P.normDim(d.dim),
          }
          if not opts.all and #fixes >= 4 then
            pos = L.solve(fixes)
            if pos and pos.res <= 0.5 then break end
            pos = nil
          end
        end
      end
    elseif ev == "timer" and a == timer then
      timer = nil
      break
    end
  end
  if timer then os.cancelTimer(timer) end
  if not wasOpen then modem.close(L.CHANNEL) end

  local use = fixes
  local ours = {}
  for _, f in ipairs(fixes) do if f.dim then ours[#ours + 1] = f end end
  if #ours >= 4 then use = ours end
  local err
  if not pos then pos, err = L.robustSolve(use) end
  if not pos then return nil, err, fixes end
  pos.bx, pos.by, pos.bz = math.floor(pos.x + 0.5), math.floor(pos.y + 0.5), math.floor(pos.z + 0.5)
  pos.dim = majorityDim(use)
  pos.n = #use
  pos.fixes = fixes
  return pos
end

return L
]]
FILES["lib/log.lua"] = [[
-- Logger: keeps the last lines in memory (for on-screen consoles) and appends to a
-- size-capped file so in-game problems can be reported afterwards.

local L = {}
L.__index = L

local LEVELS = { debug = 1, info = 2, warn = 3, error = 4 }

--- opts: path (file, optional), keep (lines in memory), maxBytes (rotate size), echo (print lines)
function L.new(opts)
  opts = opts or {}
  return setmetatable({
    path = opts.path,
    keep = opts.keep or 40,
    maxBytes = opts.maxBytes or 24000,
    echo = opts.echo,
    level = LEVELS[opts.level or "info"] or 2,
    lines = {},
    seq = 0,
  }, L)
end

function L:write(level, fmt, ...)
  if (LEVELS[level] or 2) < self.level then return end
  local ok, msg = pcall(string.format, fmt, ...)
  if not ok then msg = tostring(fmt) end
  local t = os.epoch("utc")
  local secs = math.floor(t / 1000) % 86400
  local stamp = string.format("%02d:%02d:%02d", math.floor(secs / 3600), math.floor(secs / 60) % 60, secs % 60)
  local line = stamp .. " " .. level:sub(1, 1):upper() .. " " .. msg
  self.seq = self.seq + 1
  local lines = self.lines
  lines[#lines + 1] = { seq = self.seq, level = level, text = line }
  if #lines > self.keep then table.remove(lines, 1) end
  if self.echo then print(line) end
  if self.path then self:append(line) end
end

function L:append(line)
  pcall(function()
    if fs.exists(self.path) and fs.getSize(self.path) > self.maxBytes then
      local old = self.path .. ".old"
      if fs.exists(old) then fs.delete(old) end
      fs.move(self.path, old)
    end
    local h = fs.open(self.path, "a")
    if h then
      h.writeLine(line)
      h.close()
    end
  end)
end

function L:debug(...) self:write("debug", ...) end
function L:info(...) self:write("info", ...) end
function L:warn(...) self:write("warn", ...) end
function L:error(...) self:write("error", ...) end

return L
]]
FILES["lib/net.lua"] = [[
-- Signed rednet messaging over ender modems.
--
-- Every message is an envelope:
--   { v = 1, f = fromId, t = toId|-1, ts = epochMs, n = nonce, b = "<serialized body>", m = hmac }
-- m = HMAC-SHA256(secret, "v|f|t|ts|n|b"). The secret itself is never transmitted.
-- Receivers drop anything that is not ours, too old, replayed, or badly signed, before
-- unserializing it. Who may do *what* (allowlists) is decided by the caller.

local sha2 = require("lib.sha2")
local ser = require("lib.ser")
local P = require("lib.proto")
local U = require("lib.util")

local Net = {}
Net.__index = Net

--- opts: secret, dim (string or function returning one), window (seconds), maxBody (bytes)
function Net.new(opts)
  local self = setmetatable({}, Net)
  self.secret = assert(opts.secret, "net: secret required")
  self.id = os.getComputerID()
  self.window = (opts.window or 30) * 1000
  self.maxBody = opts.maxBody or 65536
  self.protocol = opts.protocol or P.PROTOCOL
  if type(opts.dim) == "function" then self.dimFn = opts.dim
  else
    local d = opts.dim
    self.dimFn = function() return d end
  end
  self.seq = 0
  self.seen, self.seenCount = {}, 0
  self.stats = { sent = 0, recv = 0, rejected = 0, reasons = {}, last = {} }
  math.randomseed(os.epoch("utc") % 2147483647 + self.id * 7919)
  return self
end

--- Opens rednet on the first wireless modem. Returns true if one is available.
function Net:open()
  if self.side and peripheral.getType(self.side) == "modem" and rednet.isOpen(self.side) then
    return true
  end
  local _, side = U.findWirelessModem()
  self.side = side
  if not side then return false end
  if not rednet.isOpen(side) then rednet.open(side) end
  return true
end

function Net:isUp()
  return self.side ~= nil and peripheral.getType(self.side) == "modem" and rednet.isOpen(self.side)
end

local function isInt(x)
  return type(x) == "number" and x == math.floor(x) and x > -1e15 and x < 1e16
end

local function macInput(e)
  return string.format("%d|%d|%d|%d|%s|%s", e.v, e.f, e.t, e.ts, e.n, e.b)
end

function Net:wrap(to, body)
  if body.dim == nil then body.dim = self.dimFn() end
  self.seq = self.seq + 1
  local e = {
    v = P.VERSION, f = self.id, t = to, ts = os.epoch("utc"),
    n = string.format("%x.%x", self.seq, math.random(0, 0xffffff)),
    b = ser.serialize(body),
  }
  e.m = sha2.hmacHex(self.secret, macInput(e))
  return e
end

--- Sends a body table to one computer. Returns false if no modem is available.
function Net:send(to, body)
  if not self:open() then return false end
  rednet.send(to, self:wrap(to, body), self.protocol)
  self.stats.sent = self.stats.sent + 1
  return true
end

function Net:broadcast(body)
  if not self:open() then return false end
  rednet.broadcast(self:wrap(P.BROADCAST, body), self.protocol)
  self.stats.sent = self.stats.sent + 1
  return true
end

function Net:reject(sender, reason)
  local s = self.stats
  s.rejected = s.rejected + 1
  s.reasons[reason] = (s.reasons[reason] or 0) + 1
  table.insert(s.last, 1, { from = sender, reason = reason, t = os.epoch("utc") })
  if #s.last > 8 then table.remove(s.last) end
  return nil, reason
end

function Net:pruneSeen(now)
  if self.seenCount < 400 then return end
  local n = 0
  for k, exp in pairs(self.seen) do
    if exp < now then self.seen[k] = nil else n = n + 1 end
  end
  self.seenCount = n
end

--- Checks a rednet_message. Returns fromId, body  or  nil, reason.
--- Messages for other protocols or other computers return nil without counting as rejected.
function Net:unwrap(sender, e, protocol)
  if protocol ~= self.protocol then return nil, "protocol" end
  if type(e) ~= "table" then return self:reject(sender, "format") end
  if not isInt(e.t) then return self:reject(sender, "format") end
  if e.t ~= self.id and e.t ~= P.BROADCAST then return nil, "not for me" end
  if e.v ~= P.VERSION or not isInt(e.f) or not isInt(e.ts)
      or type(e.n) ~= "string" or type(e.b) ~= "string" or type(e.m) ~= "string" then
    return self:reject(sender, "format")
  end
  if #e.b > self.maxBody or #e.n > 40 then return self:reject(sender, "too big") end
  if e.f ~= sender then return self:reject(sender, "sender mismatch") end
  local now = os.epoch("utc")
  if math.abs(now - e.ts) > self.window then return self:reject(sender, "expired") end
  local key = e.f .. ":" .. e.n
  if self.seen[key] then return self:reject(sender, "replay") end
  if sha2.hmacHex(self.secret, macInput(e)) ~= e.m then return self:reject(sender, "bad signature") end
  self.seen[key] = e.ts + self.window
  self.seenCount = self.seenCount + 1
  self:pruneSeen(now)
  local body = ser.unserialize(e.b)
  if type(body) ~= "table" or type(body.type) ~= "string" then return self:reject(sender, "body") end
  body.dim = P.normDim(body.dim)
  self.stats.recv = self.stats.recv + 1
  return e.f, body
end

--- Blocks until a valid message arrives (or timeout). Other events are discarded,
--- so only call this from a coroutine dedicated to receiving.
function Net:receive(timeout)
  local timer = timeout and os.startTimer(timeout)
  while true do
    local ev, a, b, c = os.pullEvent()
    if ev == "rednet_message" then
      local from, body = self:unwrap(a, b, c)
      if from then
        if timer then os.cancelTimer(timer) end
        return from, body
      end
    elseif ev == "timer" and a == timer then
      return nil
    end
  end
end

return Net
]]
FILES["lib/proto.lua"] = [[
-- Protocol constants shared by every fleet program.

local P = {}

P.PROTOCOL = "turtlegps"   -- rednet protocol name
P.VERSION = 1              -- envelope format version
P.BROADCAST = -1           -- envelope "to" value for broadcasts

-- Message types. Every body is a table { type = ..., dim = <sender's dimension>, ... }.
P.HB = "hb"                -- turtle -> server: heartbeat / telemetry
P.HB_ACK = "hb_ack"        -- server -> turtle: heartbeat acknowledged (+ queued commands later)
P.VIEW_REQ = "view_req"    -- ui client -> server: give me the map view for a dimension
P.VIEW = "view"            -- server -> ui client
P.ACTION = "action"        -- ui client -> server: forget turtle, ack alert, ... (allowlisted)
P.ACTION_R = "action_r"    -- server -> ui client: result of an action
P.ALERT = "alert"          -- server -> ui clients: a new alert was raised
P.UPD_OFFER = "upd_offer"  -- server -> all: new code version available
P.UPD_REQ = "upd_req"      -- device -> server: send me the files I am missing
P.UPD_FILE = "upd_file"    -- server -> device: one file
P.UPD_END = "upd_end"      -- server -> device: manifest, all files sent

-- Headings: 0 = north (-z), 1 = east (+x), 2 = south (+z), 3 = west (-x)
P.HEADING_NAME = { [0] = "N", [1] = "E", [2] = "S", [3] = "W" }
P.DX = { [0] = 0, [1] = 1, [2] = 0, [3] = -1 }
P.DZ = { [0] = -1, [1] = 0, [2] = 1, [3] = 0 }

function P.headingFromDelta(dx, dz)
  if dx == 0 and dz == -1 then return 0 end
  if dx == 1 and dz == 0 then return 1 end
  if dx == 0 and dz == 1 then return 2 end
  if dx == -1 and dz == 0 then return 3 end
  return nil
end

-- Dimensions. Canonical ids drop the "minecraft:" prefix.
P.DIM_ORDER = { "overworld", "the_nether", "the_end" }

local aliases = {
  overworld = "overworld", ow = "overworld", world = "overworld",
  nether = "the_nether", the_nether = "the_nether",
  ["end"] = "the_end", the_end = "the_end",
}

function P.normDim(d)
  if type(d) ~= "string" or d == "" then return nil end
  d = d:lower()
  local short = d:match("^minecraft:(.+)$") or d
  return aliases[short] or d
end

local labels = { overworld = "Overworld", the_nether = "Nether", the_end = "End" }

function P.dimLabel(d)
  if not d then return "Unknown" end
  if labels[d] then return labels[d] end
  local s = d:match(":(.+)$") or d
  return (s:gsub("_", " "):gsub("^%l", string.upper))
end

local shorts = { overworld = "OVR", the_nether = "NTH", the_end = "END" }

function P.dimShort(d)
  if shorts[d] then return shorts[d] end
  return P.dimLabel(d):sub(1, 3):upper()
end

return P
]]
FILES["lib/ser.lua"] = [=[
-- Compact, deterministic serializer (keys sorted) and a sandboxed unserializer.
-- Same output in-game and in the mock harness, so signatures and saved files match.

local format, concat, sort = string.format, table.concat, table.sort
local floor, huge = math.floor, math.huge

local M = {}

local escapes = { ["\n"] = "\\n", ["\r"] = "\\r", ["\t"] = "\\t", ['"'] = '\\"', ["\\"] = "\\\\" }

local function quote(s)
  return '"' .. s:gsub('[%c"\\\128-\255]', function(c)
    return escapes[c] or format("\\%03d", c:byte())
  end) .. '"'
end

local function num(n)
  if n ~= n then return "0/0" end
  if n == huge then return "1/0" end
  if n == -huge then return "-1/0" end
  if n == floor(n) and n >= -9007199254740992 and n <= 9007199254740992 then
    return format("%d", n)
  end
  local s = format("%.14g", n)
  if tonumber(s) ~= n then s = format("%.17g", n) end
  return s
end

local keywords = {}
for w in ([[and break do else elseif end false for function goto if in
  local nil not or repeat return then true until while]]):gmatch("%a+") do keywords[w] = true end

local function keyOrder(a, b)
  local ta, tb = type(a), type(b)
  if ta ~= tb then return ta < tb end
  return a < b
end

local function write(v, out, seen)
  local t = type(v)
  if t == "string" then out[#out + 1] = quote(v)
  elseif t == "number" then out[#out + 1] = num(v)
  elseif t == "boolean" or t == "nil" then out[#out + 1] = tostring(v)
  elseif t == "table" then
    if seen[v] then error("ser: cannot serialize a table that contains itself", 0) end
    seen[v] = true
    out[#out + 1] = "{"
    local n = #v
    for i = 1, n do
      write(v[i], out, seen)
      out[#out + 1] = ","
    end
    local keys = {}
    for k in pairs(v) do
      local tk = type(k)
      if not (tk == "number" and k >= 1 and k <= n and k == floor(k)) then
        if tk ~= "string" and tk ~= "number" and tk ~= "boolean" then
          error("ser: cannot serialize key of type " .. tk, 0)
        end
        keys[#keys + 1] = k
      end
    end
    sort(keys, keyOrder)
    for _, k in ipairs(keys) do
      if type(k) == "string" and k:match("^[%a_][%w_]*$") and not keywords[k] then
        out[#out + 1] = k
      else
        out[#out + 1] = "["
        write(k, out, seen)
        out[#out + 1] = "]"
      end
      out[#out + 1] = "="
      write(v[k], out, seen)
      out[#out + 1] = ","
    end
    if out[#out] == "," then out[#out] = "}" else out[#out + 1] = "}" end
    seen[v] = nil
  else
    error("ser: cannot serialize a " .. t, 0)
  end
end

function M.serialize(v)
  local out = {}
  write(v, out, {})
  return concat(out)
end

--- Returns the value, or nil plus an error message. Runs with an empty environment.
function M.unserialize(s)
  if type(s) ~= "string" then return nil, "not a string" end
  local fn, err = load("return " .. s, "=ser", "t", {})
  if not fn then return nil, err end
  local ok, v = pcall(fn)
  if not ok then return nil, v end
  return v
end

return M
]=]
FILES["lib/sha2.lua"] = [[
-- SHA-256 and HMAC-SHA256 in pure Lua (CC:Tweaked / Lua 5.2, uses bit32).
-- Used to sign every fleet message so the shared secret never goes over the air.

local band, bxor, bnot = bit32.band, bit32.bxor, bit32.bnot
local rrotate, rshift = bit32.rrotate, bit32.rshift
local byte, char, rep, format = string.byte, string.char, string.rep, string.format
local concat = table.concat

local K = {
  0x428a2f98, 0x71374491, 0xb5c0fbcf, 0xe9b5dba5, 0x3956c25b, 0x59f111f1, 0x923f82a4, 0xab1c5ed5,
  0xd807aa98, 0x12835b01, 0x243185be, 0x550c7dc3, 0x72be5d74, 0x80deb1fe, 0x9bdc06a7, 0xc19bf174,
  0xe49b69c1, 0xefbe4786, 0x0fc19dc6, 0x240ca1cc, 0x2de92c6f, 0x4a7484aa, 0x5cb0a9dc, 0x76f988da,
  0x983e5152, 0xa831c66d, 0xb00327c8, 0xbf597fc7, 0xc6e00bf3, 0xd5a79147, 0x06ca6351, 0x14292967,
  0x27b70a85, 0x2e1b2138, 0x4d2c6dfc, 0x53380d13, 0x650a7354, 0x766a0abb, 0x81c2c92e, 0x92722c85,
  0xa2bfe8a1, 0xa81a664b, 0xc24b8b70, 0xc76c51a3, 0xd192e819, 0xd6990624, 0xf40e3585, 0x106aa070,
  0x19a4c116, 0x1e376c08, 0x2748774c, 0x34b0bcb5, 0x391c0cb3, 0x4ed8aa4a, 0x5b9cca4f, 0x682e6ff3,
  0x748f82ee, 0x78a5636f, 0x84c87814, 0x8cc70208, 0x90befffa, 0xa4506ceb, 0xbef9a3f7, 0xc67178f2,
}

local M32 = 0xffffffff
local W = {}

local function compress(H, s, off)
  for j = 1, 16 do
    local a, b, c, d = byte(s, off + 1, off + 4)
    W[j] = ((a * 256 + b) * 256 + c) * 256 + d
    off = off + 4
  end
  for j = 17, 64 do
    local v15, v2 = W[j - 15], W[j - 2]
    local s0 = bxor(rrotate(v15, 7), rrotate(v15, 18), rshift(v15, 3))
    local s1 = bxor(rrotate(v2, 17), rrotate(v2, 19), rshift(v2, 10))
    W[j] = band(W[j - 16] + s0 + W[j - 7] + s1, M32)
  end
  local a, b, c, d, e, f, g, h = H[1], H[2], H[3], H[4], H[5], H[6], H[7], H[8]
  for j = 1, 64 do
    local S1 = bxor(rrotate(e, 6), rrotate(e, 11), rrotate(e, 25))
    local ch = bxor(band(e, f), band(bnot(e), g))
    local t1 = h + S1 + ch + K[j] + W[j]
    local S0 = bxor(rrotate(a, 2), rrotate(a, 13), rrotate(a, 22))
    local maj = bxor(band(a, b), band(a, c), band(b, c))
    h, g, f, e, d, c, b = g, f, e, band(d + t1, M32), c, b, a
    a = band(t1 + S0 + maj, M32)
  end
  H[1] = band(H[1] + a, M32); H[2] = band(H[2] + b, M32)
  H[3] = band(H[3] + c, M32); H[4] = band(H[4] + d, M32)
  H[5] = band(H[5] + e, M32); H[6] = band(H[6] + f, M32)
  H[7] = band(H[7] + g, M32); H[8] = band(H[8] + h, M32)
end

local function word(w)
  return char(band(rshift(w, 24), 255), band(rshift(w, 16), 255), band(rshift(w, 8), 255), band(w, 255))
end

local M = {}

--- Raw 32-byte SHA-256 digest of a string.
function M.sha256(msg)
  local len = #msg
  local bits = len * 8
  local pad = (64 - (len + 9) % 64) % 64
  msg = msg .. "\128" .. rep("\0", pad) .. word(math.floor(bits / 4294967296)) .. word(bits % 4294967296)
  local H = { 0x6a09e667, 0xbb67ae85, 0x3c6ef372, 0xa54ff53a, 0x510e527f, 0x9b05688c, 0x1f83d9ab, 0x5be0cd19 }
  for off = 0, #msg - 1, 64 do compress(H, msg, off) end
  local out = {}
  for i = 1, 8 do out[i] = word(H[i]) end
  return concat(out)
end

function M.hex(bin)
  return (bin:gsub(".", function(c) return format("%02x", byte(c)) end))
end

local padCache = {}

local function pads(key)
  local p = padCache[key]
  if p then return p[1], p[2] end
  local k = key
  if #k > 64 then k = M.sha256(k) end
  k = k .. rep("\0", 64 - #k)
  local i, o = {}, {}
  for n = 1, 64 do
    local b = byte(k, n)
    i[n] = char(bxor(b, 0x36))
    o[n] = char(bxor(b, 0x5c))
  end
  local ipad, opad = concat(i), concat(o)
  padCache = { [key] = { ipad, opad } }
  return ipad, opad
end

--- Raw 32-byte HMAC-SHA256.
function M.hmac(key, msg)
  local ipad, opad = pads(key)
  return M.sha256(opad .. M.sha256(ipad .. msg))
end

function M.hmacHex(key, msg) return M.hex(M.hmac(key, msg)) end
function M.sha256Hex(msg) return M.hex(M.sha256(msg)) end

return M
]]
FILES["lib/store.lua"] = [[
-- Crash-safe table persistence. Writes go to <path>.tmp first, then replace the file.

local ser = require("lib.ser")

local S = {}

local function readFile(path)
  if not fs.exists(path) or fs.isDir(path) then return nil end
  local h = fs.open(path, "r")
  if not h then return nil end
  local s = h.readAll()
  h.close()
  return s
end

--- Returns the stored table, or `default` when the file is missing or corrupt.
function S.load(path, default)
  for _, p in ipairs({ path, path .. ".tmp" }) do
    local s = readFile(p)
    if s then
      local v = ser.unserialize(s)
      if v ~= nil then return v end
    end
  end
  return default
end

--- Returns true on success, or false plus an error (for example "Out of space").
function S.save(path, value)
  local data = ser.serialize(value)
  local tmp = path .. ".tmp"
  local dir = fs.getDir(path)
  if dir ~= "" and not fs.exists(dir) then fs.makeDir(dir) end
  local h, err = fs.open(tmp, "w")
  if not h then return false, err end
  local ok, werr = pcall(function()
    h.write(data)
    h.close()
  end)
  if not ok then
    pcall(h.close)
    return false, werr
  end
  if fs.exists(path) then fs.delete(path) end
  fs.move(tmp, path)
  return true
end

function S.readFile(path) return readFile(path) end

function S.writeFile(path, data)
  local dir = fs.getDir(path)
  if dir ~= "" and not fs.exists(dir) then fs.makeDir(dir) end
  local h, err = fs.open(path, "w")
  if not h then return false, err end
  h.write(data)
  h.close()
  return true
end

return S
]]
FILES["lib/update.lua"] = [[
-- Over-the-air code updates, signed like every other fleet message.
--
-- The control computer's /fleet code is the fleet's code. Devices learn the server's
-- version from heartbeat acks / offers, request the files whose hashes differ, verify
-- each against the server's manifest, back up the old code to /fleet.old, swap and
-- reboot. boot.lua rolls back automatically if the new code crashes 3 times in a row.

local sha2 = require("lib.sha2")
local store = require("lib.store")
local P = require("lib.proto")

local Up = {}
Up.ROOT = "/fleet"
Up.BACKUP = "/fleet.old"
Up.MANIFEST = "/fleet/manifest"
Up.STATE = "/fleet/data/update"

local function isCode(rel)
  return not (rel == "config.lua" or rel == "manifest" or rel:sub(1, 5) == "data/" or rel:find("%.tmp$"))
end

local function safePath(rel)
  return type(rel) == "string" and rel ~= "" and not rel:find("%.%.") and rel:sub(1, 1) ~= "/"
    and not rel:find("\\") and isCode(rel)
end
Up.safePath = safePath

--- Lists code files under root as paths relative to it.
function Up.listCode(root)
  root = root or Up.ROOT
  local out = {}
  local function walk(dir, rel)
    for _, name in ipairs(fs.list(dir)) do
      local full, r = fs.combine(dir, name), rel == "" and name or (rel .. "/" .. name)
      if fs.isDir(full) then walk(full, r)
      elseif isCode(r) then out[#out + 1] = r end
    end
  end
  if fs.exists(root) then walk(root, "") end
  table.sort(out)
  return out
end

function Up.version(files)
  local lines = {}
  for path, hash in pairs(files) do lines[#lines + 1] = path .. "=" .. hash end
  table.sort(lines)
  return sha2.sha256Hex(table.concat(lines, "\n")):sub(1, 8)
end

--- Hashes every code file (yields between files: call from its own coroutine).
function Up.computeManifest(root)
  root = root or Up.ROOT
  local files = {}
  for _, rel in ipairs(Up.listCode(root)) do
    files[rel] = sha2.sha256Hex(store.readFile(fs.combine(root, rel)) or "")
    os.queueEvent("fleet_yield")
    os.pullEvent("fleet_yield")
  end
  return { files = files, ver = Up.version(files) }
end

function Up.readManifest()
  local m = store.load(Up.MANIFEST, nil)
  if type(m) == "table" and type(m.files) == "table" then return m end
  return nil
end

function Up.myVersion()
  local m = Up.readManifest()
  return m and m.ver or "none"
end

--- Restores /fleet.old (used by boot.lua after repeated crashes of new code).
function Up.rollback()
  if not fs.exists(Up.BACKUP) then return false end
  for _, rel in ipairs(Up.listCode(Up.ROOT)) do fs.delete(fs.combine(Up.ROOT, rel)) end
  for _, rel in ipairs(Up.listCode(Up.BACKUP)) do
    fs.copy(fs.combine(Up.BACKUP, rel), fs.combine(Up.ROOT, rel))
  end
  local bm = fs.combine(Up.BACKUP, "manifest")
  if fs.exists(bm) then
    if fs.exists(Up.MANIFEST) then fs.delete(Up.MANIFEST) end
    fs.copy(bm, Up.MANIFEST)
  end
  local st = store.load(Up.STATE, {})
  st.pending, st.rolledBack = false, st.ver
  store.save(Up.STATE, st)
  return true
end

-- Device side ------------------------------------------------------------------------

local Client = {}
Client.__index = Client

--- opts: net, serverId, log, canApply (function -> bool, e.g. "turtle is idle")
function Up.client(opts)
  local m = Up.readManifest()
  local st = store.load(Up.STATE, {})
  return setmetatable({
    skip = st.rolledBack, -- a version that crashed here: only an explicit offer retries it
    net = opts.net, serverId = opts.serverId, log = opts.log,
    canApply = opts.canApply or function() return true end,
    have = m and m.files or {}, ver = m and m.ver or "none",
    want = nil, receiving = false, files = {}, deadline = 0, nextTry = 0, ready = nil,
    status = nil,
  }, Client)
end

--- Called with the server's version (from heartbeat acks and offers).
function Client:serverVersion(ver, explicit)
  if type(ver) ~= "string" or ver == self.ver or ver == "none" then return end
  if ver == self.skip and not explicit then
    self.status = "skipping " .. ver .. " (it crashed here; press U on control to retry)"
    return
  end
  self.want = ver
end

--- Feeds a verified message from the server. Returns true if it was an update message.
function Client:handle(from, body)
  if from ~= self.serverId then return false end
  if body.type == P.UPD_OFFER then
    self:serverVersion(body.ver, true)
    self.nextTry = 0
    return true
  elseif body.type == P.UPD_FILE then
    if self.receiving and safePath(body.path) and type(body.data) == "string"
        and sha2.sha256Hex(body.data) == body.hash then
      self.files[body.path] = body.data
    end
    return true
  elseif body.type == P.UPD_END then
    if self.receiving and type(body.files) == "table" then
      local missing = {}
      for path, hash in pairs(body.files) do
        if not safePath(path) then missing[#missing + 1] = tostring(path) end
        if not self.files[path] and self.have[path] ~= hash then missing[#missing + 1] = path end
      end
      self.receiving = false
      if #missing == 0 then
        self.ready = { files = body.files, ver = body.ver }
        self.status = "update " .. tostring(body.ver) .. " ready"
      else
        self.status = "update incomplete (" .. #missing .. " missing), will retry"
        self.nextTry = os.epoch("utc") + 30000
        if self.log then self.log:warn("update %s: %d files missing", tostring(body.ver), #missing) end
      end
    end
    return true
  end
  return false
end

function Client:apply()
  local r = self.ready
  -- back up the running code so boot.lua can roll back
  if fs.exists(Up.BACKUP) then fs.delete(Up.BACKUP) end
  for _, rel in ipairs(Up.listCode(Up.ROOT)) do
    fs.copy(fs.combine(Up.ROOT, rel), fs.combine(Up.BACKUP, rel))
  end
  if fs.exists(Up.MANIFEST) then fs.copy(Up.MANIFEST, fs.combine(Up.BACKUP, "manifest")) end
  for path, data in pairs(self.files) do
    if r.files[path] then
      local ok, err = store.writeFile(fs.combine(Up.ROOT, path), data)
      if not ok then
        if self.log then self.log:error("update write failed: %s", tostring(err)) end
        Up.rollback()
        return false
      end
    end
  end
  for _, rel in ipairs(Up.listCode(Up.ROOT)) do
    if not r.files[rel] then fs.delete(fs.combine(Up.ROOT, rel)) end
  end
  store.save(Up.MANIFEST, { files = r.files, ver = r.ver })
  store.save(Up.STATE, { ver = r.ver, from = self.ver, at = os.epoch("utc"), pending = true, crashes = 0 })
  if self.log then self.log:info("updated %s -> %s, rebooting", self.ver, tostring(r.ver)) end
  os.reboot()
end

--- Call periodically from the program's main coroutine.
function Client:tick()
  local now = os.epoch("utc")
  if self.ready then
    if self.canApply() then self:apply() end
    return
  end
  if self.receiving and now > self.deadline then
    self.receiving = false
    self.status = "update timed out, will retry"
    self.nextTry = now + 60000
  end
  if self.want and not self.receiving and now >= self.nextTry then
    self.receiving, self.files = true, {}
    self.deadline = now + 60000
    self.status = "downloading " .. self.want
    self.net:send(self.serverId, { type = P.UPD_REQ, have = self.have, ver = self.ver })
  end
end

-- Server side --------------------------------------------------------------------------

local Server = {}
Server.__index = Server

function Up.server(opts)
  return setmetatable({ net = opts.net, log = opts.log, manifest = nil, jobs = {}, served = 0 }, Server)
end

function Server:refresh()
  self.manifest = Up.computeManifest(Up.ROOT)
  store.save(Up.MANIFEST, self.manifest)
  return self.manifest
end

function Server:version() return self.manifest and self.manifest.ver or "none" end

function Server:offer()
  if not self.manifest then return false end
  return self.net:broadcast({ type = P.UPD_OFFER, ver = self.manifest.ver })
end

function Server:handle(from, body)
  if body.type ~= P.UPD_REQ then return false end
  if self.manifest then
    local have = type(body.have) == "table" and body.have or {}
    for _, j in ipairs(self.jobs) do
      if j.to == from then j.have = have; return true end
    end
    self.jobs[#self.jobs + 1] = { to = from, have = have }
  end
  return true
end

--- Sends queued updates. Run in its own coroutine; yields between files.
function Server:pump()
  while #self.jobs > 0 do
    local job = table.remove(self.jobs, 1)
    local m = self.manifest
    local sent = 0
    for _, path in ipairs((function()
      local ks = {}
      for k in pairs(m.files) do ks[#ks + 1] = k end
      table.sort(ks)
      return ks
    end)()) do
      local hash = m.files[path]
      if job.have[path] ~= hash then
        local data = store.readFile(fs.combine(Up.ROOT, path))
        if data then
          self.net:send(job.to, { type = P.UPD_FILE, path = path, data = data, hash = hash })
          sent = sent + 1
          sleep(0.05)
        end
      end
    end
    self.net:send(job.to, { type = P.UPD_END, files = m.files, ver = m.ver })
    self.served = self.served + 1
    if self.log then self.log:info("sent update %s to #%d (%d files)", m.ver, job.to, sent) end
  end
end

return Up
]]
FILES["lib/util.lua"] = [[
-- Small shared helpers.

local U = {}

function U.now() return os.epoch("utc") end

function U.clamp(v, lo, hi)
  if v < lo then return lo elseif v > hi then return hi end
  return v
end

function U.round(v) return math.floor(v + 0.5) end

function U.copy(t)
  local r = {}
  for k, v in pairs(t) do r[k] = v end
  return r
end

function U.deepcopy(v)
  if type(v) ~= "table" then return v end
  local r = {}
  for k, x in pairs(v) do r[k] = U.deepcopy(x) end
  return r
end

--- Fills missing keys in t from defaults (recursively for plain tables).
function U.merge(t, defaults)
  for k, v in pairs(defaults) do
    if t[k] == nil then
      t[k] = U.deepcopy(v)
    elseif type(t[k]) == "table" and type(v) == "table" and #v == 0 then
      U.merge(t[k], v)
    end
  end
  return t
end

function U.sortedKeys(t)
  local ks = {}
  for k in pairs(t) do ks[#ks + 1] = k end
  table.sort(ks, function(a, b)
    if type(a) == type(b) then return a < b end
    return type(a) < type(b)
  end)
  return ks
end

function U.count(t)
  local n = 0
  for _ in pairs(t) do n = n + 1 end
  return n
end

--- "4s", "3m", "2h", "5d" from a duration in milliseconds.
function U.age(ms)
  if not ms then return "?" end
  local s = math.floor(ms / 1000)
  if s < 0 then s = 0 end
  if s < 60 then return s .. "s" end
  if s < 3600 then return math.floor(s / 60) .. "m" end
  if s < 86400 then return math.floor(s / 3600) .. "h" end
  return math.floor(s / 86400) .. "d"
end

function U.trunc(s, n)
  s = tostring(s)
  if #s > n then return s:sub(1, n) end
  return s
end

function U.pad(s, n)
  s = U.trunc(s, n)
  return s .. string.rep(" ", n - #s)
end

function U.padLeft(s, n)
  s = U.trunc(s, n)
  return string.rep(" ", n - #s) .. s
end

function U.trim(s) return (s:gsub("^%s+", ""):gsub("%s+$", "")) end

function U.fmtPos(x, y, z)
  if type(x) == "table" then x, y, z = x.x, x.y, x.z end
  if x == nil then return "?" end
  return string.format("%d, %d, %d", math.floor(x), math.floor(y), math.floor(z))
end

function U.manhattan(a, b)
  return math.abs(a.x - b.x) + math.abs(a.y - b.y) + math.abs(a.z - b.z)
end

--- Finds the first wireless (ender or normal) modem. Returns wrapped modem and its side.
function U.findWirelessModem()
  local m = peripheral.find("modem", function(_, p) return p.isWireless and p.isWireless() end)
  if m then return m, peripheral.getName(m) end
  return nil
end

return U
]]
FILES["server/fleet.lua"] = [[
-- Control-room fleet state: turtles, GPS hosts, alerts, waypoints. No I/O loops here,
-- so it can be driven by app/control.lua in-game and by tests directly.

local P = require("lib.proto")
local U = require("lib.util")
local store = require("lib.store")

local Fleet = {}
Fleet.__index = Fleet
Fleet.PATH = "/fleet/data/fleet.db"

local MAX_ALERTS = 60
local GPS_LOST_AFTER = 90 -- seconds; GPS hosts heartbeat every 20s

local function num(v)
  if type(v) == "number" and v == v and v ~= math.huge and v ~= -math.huge then return v end
end
local function int(v)
  v = num(v)
  return v and math.floor(v)
end
local function str(v, n)
  if type(v) == "string" then return v:sub(1, n or 40) end
end
local function contains(list, v)
  if type(list) ~= "table" then return false end
  for _, x in ipairs(list) do if x == v then return true end end
  return false
end

function Fleet.new(cfg, log)
  return setmetatable({
    cfg = cfg, log = log,
    turtles = {}, gps = {}, alerts = {}, alertSeq = 0, waypoints = {},
    bootAt = os.epoch("utc"), dirty = false, savedAt = 0,
    ver = "none",
    denied = {},       -- recent refused requests, for the console
    onAlert = nil,     -- function(alert) when an alert is raised
    onResolve = nil,   -- function(alert, note) when a critical alert clears
  }, Fleet)
end

function Fleet:load()
  local d = store.load(Fleet.PATH, nil)
  if type(d) ~= "table" then return false end
  self.turtles = d.turtles or {}
  self.gps = d.gps or {}
  self.alerts = d.alerts or {}
  self.alertSeq = d.alertSeq or 0
  self.waypoints = d.waypoints or {}
  return true
end

function Fleet:save()
  local ok, err = store.save(Fleet.PATH, {
    turtles = self.turtles, gps = self.gps, alerts = self.alerts,
    alertSeq = self.alertSeq, waypoints = self.waypoints,
  })
  if ok then
    self.dirty = false
    self.savedAt = os.epoch("utc")
  elseif self.log then
    self.log:error("saving fleet state failed: %s", tostring(err))
  end
  return ok
end

function Fleet:saveIfDue(now, every)
  if self.dirty and now - self.savedAt >= (every or 10) * 1000 then self:save() end
end

function Fleet:deny(from, what, why)
  local now, key = os.epoch("utc"), from .. ":" .. what
  self.denyAt = self.denyAt or {}
  if self.denyAt[key] and now - self.denyAt[key] < 60000 then return end -- once a minute per sender
  self.denyAt[key] = now
  table.insert(self.denied, 1, { from = from, what = what, why = why, t = now })
  if #self.denied > 8 then table.remove(self.denied) end
  if self.log then self.log:warn("denied %s from #%d: %s", what, from, why) end
end

function Fleet:isCommander(id) return contains(self.cfg.commanders, id) end

-- Alerts --------------------------------------------------------------------------

function Fleet:findActive(key)
  for _, a in ipairs(self.alerts) do
    if a.key == key and a.active then return a end
  end
end

function Fleet:raise(key, kind, sev, subject, text)
  local a = self:findActive(key)
  if a then
    a.text = text
    return a
  end
  self.alertSeq = self.alertSeq + 1
  a = {
    id = self.alertSeq, key = key, kind = kind, sev = sev, text = text,
    dim = subject.dim, tid = subject.id, t = os.epoch("utc"), active = true, acked = false,
  }
  table.insert(self.alerts, 1, a)
  while #self.alerts > MAX_ALERTS do
    local victim
    for i = #self.alerts, 1, -1 do
      if not self.alerts[i].active then victim = i; break end
    end
    table.remove(self.alerts, victim or #self.alerts)
  end
  self.dirty = true
  if self.log then self.log:warn("ALERT %s", text) end
  if self.onAlert then self.onAlert(a) end
  return a
end

function Fleet:resolve(key, note)
  local a = self:findActive(key)
  if not a then return end
  a.active = false
  a.resolvedAt = os.epoch("utc")
  a.note = note
  self.dirty = true
  if self.log then self.log:info("resolved: %s%s", a.text, note and (" (" .. note .. ")") or "") end
  if a.sev >= 3 and self.onResolve then self.onResolve(a, note) end
end

function Fleet:activeAlerts()
  local out = {}
  for _, a in ipairs(self.alerts) do if a.active then out[#out + 1] = a end end
  table.sort(out, function(x, y)
    if x.acked ~= y.acked then return not x.acked end
    if x.sev ~= y.sev then return x.sev > y.sev end
    return x.t > y.t
  end)
  return out
end

-- Telemetry --------------------------------------------------------------------------

local function name(t)
  return "#" .. t.id .. (t.label and (" " .. t.label) or "")
end
Fleet.name = name

function Fleet:evaluate(t)
  local id = t.id
  if t.fuel and t.fuel >= 0 then
    local thr = math.max(self.cfg.lowFuel or 0, t.reserve or 0)
    if t.fuel < thr then
      self:raise("fuel:" .. id, "lowfuel", 2, t, ("%s low fuel: %d (want %d)"):format(name(t), t.fuel, thr))
    elseif t.fuel >= thr * 1.1 then
      self:resolve("fuel:" .. id, "refuelled")
    end
  else
    self:resolve("fuel:" .. id)
  end
  if t.invTotal and t.invTotal > 0 and t.invUsed and t.invUsed >= t.invTotal then
    self:raise("full:" .. id, "full", 2, t, name(t) .. " inventory full")
  else
    self:resolve("full:" .. id, "emptied")
  end
  if t.status == "stuck" then
    self:raise("stuck:" .. id, "stuck", 3, t,
      ("%s STUCK at %s: %s"):format(name(t), U.fmtPos(t), t.msg or "?"))
  else
    self:resolve("stuck:" .. id, "moving again")
  end
  if t.status == "error" then
    self:raise("error:" .. id, "error", 2, t, ("%s error: %s"):format(name(t), t.msg or "?"))
  else
    self:resolve("error:" .. id)
  end
end

function Fleet:onTurtleHeartbeat(from, b, now)
  if type(self.cfg.turtles) == "table" and not contains(self.cfg.turtles, from) then
    self:deny(from, "heartbeat", "not in turtles allowlist")
    return nil
  end
  local t = self.turtles[from]
  if not t then
    t = { id = from, firstSeen = now }
    self.turtles[from] = t
    if self.log then self.log:info("new turtle #%d in %s", from, tostring(b.dim)) end
  end
  t.label = str(b.label, 24)
  t.dim = b.dim or t.dim
  local x, y, z = int(b.x), int(b.y), int(b.z)
  if x and y and z then
    t.x, t.y, t.z, t.posAt = x, y, z, now
  end
  t.h = int(b.h)
  if t.h and (t.h < 0 or t.h > 3) then t.h = nil end
  t.fix = str(b.fix, 8) or "none"
  t.fixAge = int(b.fixAge)
  t.gpsErr = str(b.gpsErr, 60)
  t.fuel, t.fuelMax, t.reserve = int(b.fuel), int(b.fuelMax), int(b.reserve)
  if type(b.inv) == "table" then t.invUsed, t.invTotal = int(b.inv[1]), int(b.inv[2]) end
  t.status = str(b.status, 16) or "?"
  if type(b.job) == "table" then
    t.job = str(b.job.name, 24)
    t.progress = num(b.job.progress)
  else
    t.job, t.progress = str(b.job, 24), nil
  end
  t.msg = str(b.msg, 80)
  t.ver = str(b.ver, 12)
  t.up = int(b.up)
  t.lastSeen = now
  if t.link == "lost" then self:resolve("lost:" .. from, "back online") end
  t.link = "ok"
  self:evaluate(t)
  self.dirty = true
  return { type = P.HB_ACK, ver = self.ver }
end

function Fleet:onGpsHeartbeat(from, b, now)
  local g = self.gps[from]
  if not g then
    g = { id = from }
    self.gps[from] = g
  end
  g.dim = b.dim
  g.x, g.y, g.z = int(b.x), int(b.y), int(b.z)
  g.label = str(b.label, 24)
  g.served = int(b.served)
  g.verdict = str(b.verdict, 60)
  g.ver = str(b.ver, 12)
  g.lastSeen = now
  if g.link == "lost" then self:resolve("gps:" .. from, "back online") end
  g.link = "ok"
  self.dirty = true
  return { type = P.HB_ACK, ver = self.ver }
end

--- Updates stale/lost status. Call about once a second.
function Fleet:tick(now)
  local stale, lost = (self.cfg.staleAfter or 12) * 1000, (self.cfg.lostAfter or 45) * 1000
  local grace = now - self.bootAt < lost
  for id, t in pairs(self.turtles) do
    local age = now - (t.lastSeen or 0)
    local link = age > lost and "lost" or (age > stale and "stale" or "ok")
    if link == "lost" and t.link ~= "lost" and grace then link = "stale" end
    if link ~= t.link then
      t.link = link
      self.dirty = true
      if link == "lost" then
        self:raise("lost:" .. id, "lost", 3, t, ("%s LOST in %s: silent %s, last at %s"):format(
          name(t), P.dimLabel(t.dim), U.age(age), t.x and U.fmtPos(t) or "unknown position"))
      end
    end
  end
  for id, g in pairs(self.gps) do
    local age = now - (g.lastSeen or 0)
    local link = age > GPS_LOST_AFTER * 1000 and "lost" or "ok"
    if link == "lost" and g.link ~= "lost" and now - self.bootAt < GPS_LOST_AFTER * 1000 then link = "ok" end
    if link ~= g.link then
      g.link = link
      self.dirty = true
      if link == "lost" then
        self:raise("gps:" .. id, "gps", 2, g, ("GPS host #%d (%s) offline: turtles there may lose GPS"):format(
          id, P.dimLabel(g.dim)))
      end
    end
  end
end

-- Requests ---------------------------------------------------------------------------

--- Handles one verified message. Returns a reply body or nil.
function Fleet:handle(from, body, now)
  local ty = body.type
  if ty == P.HB then
    if body.role == "gpshost" then return self:onGpsHeartbeat(from, body, now) end
    if body.role == "pocket" then return { type = P.HB_ACK, ver = self.ver } end
    return self:onTurtleHeartbeat(from, body, now)
  elseif ty == P.ACTION or ty == P.VIEW_REQ then
    if not self:isCommander(from) then
      self:deny(from, ty, "not in commanders allowlist")
      return nil
    end
    if ty == P.ACTION then
      local ok, msg = self:action(body)
      return { type = P.ACTION_R, ok = ok, msg = msg, req = body.req }
    end
    return self:view(P.normDim(body.view) or body.dim, now, true)
  end
  return nil
end

--- UI actions (local monitor, or allowlisted pockets). Returns ok, message.
function Fleet:action(a)
  if a.op == "forget" then
    local t = self.turtles[a.id]
    if not t then return false, "no such turtle" end
    self.turtles[a.id] = nil
    for _, k in ipairs({ "lost", "fuel", "full", "stuck", "error" }) do self:resolve(k .. ":" .. a.id, "forgotten") end
    self.dirty = true
    return true, "forgot " .. name(t)
  elseif a.op == "forgetGps" then
    if not self.gps[a.id] then return false, "no such GPS host" end
    self.gps[a.id] = nil
    self:resolve("gps:" .. a.id, "forgotten")
    self.dirty = true
    return true, "forgot GPS host #" .. a.id
  elseif a.op == "ack" then
    for _, al in ipairs(self.alerts) do
      if al.id == a.id then
        al.acked = true
        self.dirty = true
        return true, "acknowledged"
      end
    end
    return false, "no such alert"
  elseif a.op == "ackAll" then
    for _, al in ipairs(self.alerts) do if al.active then al.acked = true end end
    self.dirty = true
    return true, "all acknowledged"
  end
  return false, "unknown action " .. tostring(a.op)
end

local VIEW_FIELDS = {
  "id", "label", "dim", "x", "y", "z", "h", "fix", "fixAge", "gpsErr", "fuel", "fuelMax", "invUsed",
  "invTotal", "status", "job", "progress", "msg", "ver", "link", "lastSeen", "posAt",
}

--- Everything a map client needs for one dimension.
function Fleet:view(dim, now, forWire)
  dim = dim or "overworld"
  local v = {
    type = P.VIEW, now = now, view = dim, ver = self.ver,
    turtles = {}, gps = {}, waypoints = {}, players = {}, dims = {}, alerts = {},
  }
  local function dimInfo(d)
    if not v.dims[d] then v.dims[d] = { turtles = 0, lost = 0, gps = 0, gpsDown = 0 } end
    return v.dims[d]
  end
  for _, d in ipairs(P.DIM_ORDER) do dimInfo(d) end
  local flags = {}
  for _, a in ipairs(self.alerts) do
    if a.active and a.tid then flags[a.kind .. ":" .. a.tid] = true end
  end
  for _, id in ipairs(U.sortedKeys(self.turtles)) do
    local t = self.turtles[id]
    local info = dimInfo(t.dim or "unknown")
    info.turtles = info.turtles + 1
    if t.link == "lost" then info.lost = info.lost + 1 end
    if (t.dim or "unknown") == dim then
      local c = {}
      for _, f in ipairs(VIEW_FIELDS) do c[f] = t[f] end
      c.age = now - (t.lastSeen or 0)
      c.lowFuel = flags["lowfuel:" .. id]
      c.full = flags["full:" .. id]
      c.old = t.ver ~= nil and self.ver ~= "none" and t.ver ~= self.ver
      v.turtles[#v.turtles + 1] = c
    end
  end
  for _, id in ipairs(U.sortedKeys(self.gps)) do
    local g = self.gps[id]
    local info = dimInfo(g.dim or "unknown")
    info.gps = info.gps + 1
    if g.link == "lost" then info.gpsDown = info.gpsDown + 1 end
    if g.dim == dim then
      v.gps[#v.gps + 1] = { id = id, x = g.x, y = g.y, z = g.z, link = g.link, verdict = g.verdict }
    end
  end
  local garage = self.cfg.garages and self.cfg.garages[dim]
  if type(garage) == "table" and garage.x then
    v.waypoints[#v.waypoints + 1] = { name = "Garage", x = garage.x, y = garage.y, z = garage.z, kind = "garage" }
  end
  for _, wp in ipairs(self.waypoints[dim] or {}) do v.waypoints[#v.waypoints + 1] = wp end
  for _, a in ipairs(self:activeAlerts()) do
    if #v.alerts >= 20 then break end
    v.alerts[#v.alerts + 1] = {
      id = a.id, kind = a.kind, sev = a.sev, text = a.text, dim = a.dim, tid = a.tid, t = a.t, acked = a.acked,
    }
  end
  if not forWire then v.denied = self.denied end
  return v
end

return Fleet
]]
FILES["server/notify.lua"] = [[
-- Alert delivery: Advanced Peripherals Chat Box (private message to the owner) and a
-- speaker chime, both optional. Chat Box calls are queued because the peripheral has
-- a cooldown between messages.

local N = {}
N.__index = N

function N.new(cfg, log)
  local self = setmetatable({ cfg = cfg, log = log, queue = {} }, N)
  self:attach()
  return self
end

function N:attach()
  self.chat = peripheral.find("chatBox")
  self.speaker = peripheral.find("speaker")
  if self.chat and not self.cfg.owner and self.log then
    self.log:warn("Chat Box found but no owner in config: chat alerts disabled")
  end
end

function N:alert(a)
  if self.chat and self.cfg.owner then
    self.queue[#self.queue + 1] = { text = a.text, toast = a.sev >= 3 }
  end
  if self.speaker then
    pcall(self.speaker.playNote, "bell", 1, a.sev >= 3 and 18 or 12)
  end
end

function N:resolved(a, note)
  if self.chat and self.cfg.owner then
    self.queue[#self.queue + 1] = { text = "OK: " .. a.text .. (note and (" (" .. note .. ")") or "") }
  end
end

--- Run in its own coroutine.
function N:pump()
  while true do
    local item = self.queue[1]
    if item and self.chat then
      local ok, res, err = pcall(function()
        if item.toast and self.chat.sendToastToPlayer then
          return self.chat.sendToastToPlayer(item.text, "TurtleGPS alert", self.cfg.owner, "TurtleGPS")
        end
        return self.chat.sendMessageToPlayer(item.text, self.cfg.owner, "TurtleGPS")
      end)
      if ok and res then
        table.remove(self.queue, 1)
      elseif not ok then
        if self.log then self.log:warn("chat box: %s", tostring(res)) end
        table.remove(self.queue, 1)
      end
      -- res == nil/false means cooldown: retry after the sleep
      if not ok or res then sleep(1) else sleep(1.5) end
    else
      if #self.queue > 0 and not self.chat then self.queue = {} end
      sleep(0.5)
    end
  end
end

return N
]]
FILES["turtle/nav.lua"] = [[
-- Turtle position tracking: dead reckoning on every move, corrected by GPS fixes.
-- All movement must go through these functions so the tracked position stays right.
--
-- Heading: 0 = north (-z), 1 = east (+x), 2 = south (+z), 3 = west (-x).

local P = require("lib.proto")
local U = require("lib.util")
local locate = require("lib.locate")
local ser = require("lib.ser")
local store = require("lib.store")

local Nav = {}
Nav.__index = Nav

--- opts: log, dim (configured dimension or nil for auto), path (persist file)
function Nav.new(opts)
  return setmetatable({
    log = opts.log,
    cfgDim = P.normDim(opts.dim),
    dim = P.normDim(opts.dim),
    path = opts.path or "/fleet/data/nav",
    x = nil, y = nil, z = nil, h = nil,
    fixAt = nil,      -- epoch ms of the last GPS fix
    src = "none",     -- "gps" right after a fix, "dr" after dead-reckoned moves, "none" unknown
    moves = 0,        -- moves since the last fix
    gpsErr = nil,     -- why the last GPS attempt failed
    drift = nil,      -- last correction a GPS fix applied (blocks), for diagnostics
  }, Nav)
end

function Nav:known() return self.x ~= nil end

function Nav:pos() return { x = self.x, y = self.y, z = self.z } end

function Nav:save()
  -- tiny file, written after every move so a reboot resumes in the right place
  local h = fs.open(self.path, "w")
  if h then
    h.write(ser.serialize({ x = self.x, y = self.y, z = self.z, h = self.h, dim = self.dim }))
    h.close()
  end
end

function Nav:load()
  local s = store.load(self.path, nil)
  if type(s) == "table" then
    self.x, self.y, self.z, self.h = s.x, s.y, s.z, s.h
    if not self.cfgDim then self.dim = s.dim end
    if self.x then self.src = "dr" end
  end
end

--- Asks the GPS constellation where we are. Returns the locate result or nil, err.
function Nav:fix(timeout)
  local p, err = locate.locate(timeout or 2)
  if not p then
    self.gpsErr = err
    return nil, err
  end
  self.gpsErr = nil
  if p.dim then
    if self.cfgDim and p.dim ~= self.cfgDim and self.log then
      self.log:warn("GPS hosts say %s but config says %s; using GPS", p.dim, self.cfgDim)
    end
    self.dim = p.dim
  end
  if self.x and (p.bx ~= self.x or p.by ~= self.y or p.bz ~= self.z) then
    self.drift = math.abs(p.bx - self.x) + math.abs(p.by - self.y) + math.abs(p.bz - self.z)
    if self.log then
      self.log:warn("GPS corrected position by %d (was %s)", self.drift, U.fmtPos(self))
    end
  end
  self.x, self.y, self.z = p.bx, p.by, p.bz
  self.fixAt = os.epoch("utc")
  self.src = "gps"
  self.moves = 0
  self:save()
  return p
end

local function sameBlock(a, b) return a.bx == b.bx and a.by == b.by and a.bz == b.bz end

--- Works out which way we face by moving one block and asking GPS again.
--- Skipped when we are exactly where we were saved (heading is still valid then).
function Nav:calibrate()
  local saved = self.x and { x = self.x, y = self.y, z = self.z, h = self.h }
  local p0, err = self:fix()
  if not p0 then return false, "no GPS: " .. tostring(err) end
  if saved and saved.h and saved.x == p0.bx and saved.y == p0.by and saved.z == p0.bz then
    self.h = saved.h
    return true, "kept saved heading"
  end
  self.h = nil
  local fuel = turtle.getFuelLevel()
  if fuel ~= "unlimited" and fuel < 2 then return false, "need 2 fuel to find heading" end

  -- forward, back, then the same after a right turn: covers all four directions
  local tries = {
    { move = turtle.forward, undo = turtle.back, sign = 1 },
    { move = turtle.back, undo = turtle.forward, sign = -1 },
  }
  for turn = 0, 1 do
    if turn == 1 then turtle.turnRight() end
    for _, t in ipairs(tries) do
      if t.move() then
        local p1 = locate.locate(2)
        local undone = t.undo()
        if not p1 then
          self.x = nil
          return false, "lost GPS while calibrating"
        end
        local h = P.headingFromDelta((p1.bx - p0.bx) * t.sign, (p1.bz - p0.bz) * t.sign)
        if not h then return false, "unexpected GPS delta" end
        self.h = h
        if not undone then self.x, self.y, self.z = p1.bx, p1.by, p1.bz end
        self.src = "gps"
        self:save()
        return true, "heading " .. P.HEADING_NAME[h]
      end
    end
  end
  return false, "boxed in: cannot move to find heading"
end

-- Tracked movement --------------------------------------------------------------

local function after(self, ok)
  if ok then
    self.moves = self.moves + 1
    if self.src == "gps" then self.src = "dr" end
    self:save()
  end
  return ok
end

function Nav:forward()
  local ok, err = turtle.forward()
  if ok then
    if self.h and self.x then
      self.x, self.z = self.x + P.DX[self.h], self.z + P.DZ[self.h]
    else
      self.x = nil -- moved without knowing where we face: position unknown until next fix
    end
  end
  return after(self, ok), err
end

function Nav:back()
  local ok, err = turtle.back()
  if ok then
    if self.h and self.x then
      self.x, self.z = self.x - P.DX[self.h], self.z - P.DZ[self.h]
    else
      self.x = nil
    end
  end
  return after(self, ok), err
end

function Nav:up()
  local ok, err = turtle.up()
  if ok and self.y then self.y = self.y + 1 end
  return after(self, ok), err
end

function Nav:down()
  local ok, err = turtle.down()
  if ok and self.y then self.y = self.y - 1 end
  return after(self, ok), err
end

function Nav:turnLeft()
  local ok, err = turtle.turnLeft()
  if ok and self.h then self.h = (self.h + 3) % 4; self:save() end
  return ok, err
end

function Nav:turnRight()
  local ok, err = turtle.turnRight()
  if ok and self.h then self.h = (self.h + 1) % 4; self:save() end
  return ok, err
end

--- Turns to face heading h (fewest turns).
function Nav:face(h)
  if not self.h then return false, "heading unknown" end
  local d = (h - self.h) % 4
  if d == 1 then return self:turnRight()
  elseif d == 2 then self:turnRight(); return self:turnRight()
  elseif d == 3 then return self:turnLeft() end
  return true
end

--- Snapshot for heartbeats.
function Nav:telemetry()
  local now = os.epoch("utc")
  return {
    x = self.x, y = self.y, z = self.z, h = self.h, dim = self.dim,
    fix = self.x and self.src or "none",
    fixAge = self.fixAt and math.floor((now - self.fixAt) / 1000) or nil,
    moves = self.moves,
    gpsErr = self.gpsErr,
  }
end

return Nav
]]
FILES["ui/app.lua"] = [=[
-- The map application. One renderer for every screen size:
--   wide  (monitors, 50+ columns): top bar, map, side panel, status line
--   compact (pocket 26x20): top bar, full map, overlays for details/alerts/menu
-- Data comes from a "source" with :view(dim) and :action(a) (local server or rednet).

local P = require("lib.proto")
local U = require("lib.util")
local FB = require("ui.fb")
local Map = require("ui.map")
local Glyphs = require("ui.glyphs")

local App = {}
App.__index = App

local SEV_COLOR = { [1] = colors.lightGray, [2] = colors.orange, [3] = colors.red }
local BAR_BG, BTN_BG, ON_BG = colors.gray, colors.lightGray, colors.green
local PANEL_BG = colors.black

--- opts: term, source, kind ("monitor"|"pocket"|"term"), side (monitor side), dim, ascii, title
function App.new(opts)
  local self = setmetatable({
    term = opts.term, source = opts.source, kind = opts.kind or "term", side = opts.side,
    G = Glyphs.get(opts.ascii),
    dim = P.normDim(opts.dim) or "overworld",
    views = {},
    layers = { turtles = true, players = true, waypoints = true, terrain = true },
    sel = nil, panel = nil, target = nil,
    toast = nil, toastUntil = 0,
    buttons = {}, hits = {},
    blink = false, data = nil,
    title = opts.title or "TurtleGPS",
  }, App)
  self.fb = FB.new(opts.term)
  return self
end

function App:say(msg, secs)
  self.toast = msg
  self.toastUntil = os.epoch("utc") + (secs or 4) * 1000
end

-- Data ---------------------------------------------------------------------------------

function App:refresh()
  local ok, d = pcall(self.source.view, self.source, self.dim)
  if ok and d then self.data = d end
end

function App:turtle(id)
  for _, t in ipairs(self.data and self.data.turtles or {}) do
    if t.id == id then return t end
  end
end

function App:dims()
  local list, seen = {}, {}
  for _, d in ipairs(P.DIM_ORDER) do list[#list + 1] = d; seen[d] = true end
  for d in pairs(self.data and self.data.dims or {}) do
    if not seen[d] then list[#list + 1] = d; seen[d] = true end
  end
  return list
end

--- Viewport for the current dimension, centred on the garage or the fleet the first time.
function App:view()
  local v = self.views[self.dim]
  if v then return v end
  local d = self.data
  if not d or d.view ~= self.dim then return Map.new(0, 0) end
  local cx, cz
  for _, wp in ipairs(d.waypoints or {}) do
    if wp.kind == "garage" then cx, cz = wp.x, wp.z end
  end
  if not cx then
    local n, sx, sz = 0, 0, 0
    for _, t in ipairs(d.turtles) do
      if t.x then n, sx, sz = n + 1, sx + t.x, sz + t.z end
    end
    if n > 0 then cx, cz = math.floor(sx / n), math.floor(sz / n) end
  end
  v = Map.new(cx or 0, cz or 0)
  self.views[self.dim] = v
  return v
end

function App:centerOn(x, z)
  local v = self:view()
  v.cx, v.cz = x, z
end

function App:setDim(d)
  if d == self.dim then return end
  self.dim = d
  self.sel = nil
  self.target = nil
  self:refresh()
end

function App:cycleDim(step)
  local list = self:dims()
  local idx = 1
  for i, d in ipairs(list) do if d == self.dim then idx = i end end
  self:setDim(list[(idx - 1 + step) % #list + 1])
end

function App:select(id)
  self.sel = id
  self.panel = nil
  local t = id and self:turtle(id)
  if t and t.x then
    local v = self:view()
    local r = self.rects and self.rects.map
    if r then
      local col, row = Map.toScreen(v, r, t.x, t.z)
      if not Map.inside(r, col, row) then self:centerOn(t.x, t.z) end
    end
  end
end

function App:act(a)
  local ok, msg = self.source:action(a)
  self:say(msg or (ok and "done" or "failed"))
  self:refresh()
  return ok
end

-- Layout -------------------------------------------------------------------------------

function App:layout()
  local w, h = self.fb.w, self.fb.h
  local R = {}
  self.compact = w < 50 or h < 16
  if self.compact then
    R.bar = { x = 1, y = 1, w = w, h = 1 }
    R.map = { x = 1, y = 2, w = w, h = h - 2 }
    R.status = { x = 1, y = h, w = w, h = 1 }
  else
    local bh = h >= 40 and 3 or 1
    local pw = U.clamp(math.floor(w * 0.3), 24, 42)
    R.bar = { x = 1, y = 1, w = w, h = bh }
    R.map = { x = 1, y = bh + 1, w = w - pw, h = h - bh - 1 }
    R.side = { x = w - pw + 1, y = bh + 1, w = pw, h = h - bh - 1 }
    R.status = { x = 1, y = h, w = w, h = 1 }
  end
  self.rects = R
  return R
end

function App:button(x, y, w, h, label, fn, fg, bg)
  local fb = self.fb
  fb:fill(x, y, w, h, " ", fg or colors.black, bg or BTN_BG)
  local ly = y + math.floor((h - 1) / 2)
  local lx = x + math.max(0, math.floor((w - #label) / 2))
  fb:text(lx, ly, label, fg or colors.black, bg or BTN_BG, w)
  self.buttons[#self.buttons + 1] = { x1 = x, y1 = y, x2 = x + w - 1, y2 = y + h - 1, fn = fn }
  return x + w
end

function App:buttonAt(x, y)
  for i = #self.buttons, 1, -1 do
    local b = self.buttons[i]
    if x >= b.x1 and x <= b.x2 and y >= b.y1 and y <= b.y2 then return b end
  end
end

-- Colours -------------------------------------------------------------------------------

function App:turtleColor(t)
  if t.link == "lost" then return self.blink and colors.red or colors.gray end
  if t.link == "stale" then return colors.lightGray end
  if t.status == "stuck" or t.status == "error" then return colors.red end
  if t.lowFuel then return colors.orange end
  if t.full then return colors.yellow end
  if t.status == "idle" or t.status == "parked" or t.status == "locating" then return colors.white end
  return colors.lime
end

local function severity(t)
  if t.link == "lost" then return 5 end
  if t.status == "stuck" or t.status == "error" then return 4 end
  if t.lowFuel then return 3 end
  if t.full then return 2 end
  return 1
end

-- Drawing --------------------------------------------------------------------------------

function App:draw()
  local R = self:layout()
  local fb = self.fb
  self.buttons = {}
  fb:clear(colors.black)
  if not self.data then
    fb:text(2, 2, self.title .. ": waiting for data...", colors.yellow)
    fb:flush()
    return
  end
  self:drawMap(R.map)
  if self.compact then
    self:drawCompactBar(R.bar)
    if self.panel == "alerts" then self:drawAlertsOverlay(R.map)
    elseif self.panel == "menu" then self:drawMenuOverlay(R.map)
    elseif self.panel == "point" then self:drawPointSheet(R.map)
    elseif self.sel and self:turtle(self.sel) then self:drawDetailSheet(R.map) end
  else
    self:drawWideBar(R.bar)
    self:drawSide(R.side)
  end
  self:drawStatus(R.status)
  fb:flush()
end

function App:drawMap(r)
  local fb, G, d = self.fb, self.G, self.data
  local v = self:view()
  self.hits = {}
  fb:fill(r.x, r.y, r.w, r.h, " ", colors.gray, colors.black)

  -- grid intersections every 16/32/64... blocks
  local cols, rows = Map.gridCells(v, r)
  for _, row in ipairs(rows) do
    for _, col in ipairs(cols) do fb:set(col, row, G.grid, colors.gray) end
  end

  if self.layers.waypoints then
    for _, g in ipairs(d.gps or {}) do
      if g.x then
        local col, row = Map.toScreen(v, r, g.x, g.z)
        if Map.inside(r, col, row) then
          fb:set(col, row, G.gps, g.link == "lost" and colors.red or colors.brown)
        end
      end
    end
    for _, wp in ipairs(d.waypoints or {}) do
      local col, row = Map.toScreen(v, r, wp.x, wp.z)
      if Map.inside(r, col, row) then
        local garage = wp.kind == "garage"
        fb:set(col, row, garage and G.garage or G.waypoint, garage and colors.cyan or colors.magenta)
        if not self.compact then
          fb:text(col + 1, row, wp.name or "", colors.lightGray, nil, r.x + r.w - col - 1)
        end
      end
    end
  end

  if self.layers.players then
    for _, p in ipairs(d.players or {}) do
      local col, row = Map.toScreen(v, r, p.x, p.z)
      if Map.inside(r, col, row) then
        fb:set(col, row, G.player, colors.yellow)
        if not self.compact then fb:text(col + 1, row, p.name or "", colors.yellow, nil, r.x + r.w - col - 1) end
      end
    end
  end

  if self.target and self.target.dim == self.dim then
    local col, row = Map.toScreen(v, r, self.target.x, self.target.z)
    if Map.inside(r, col, row) then fb:set(col, row, G.target, colors.magenta, colors.black) end
  end

  if self.layers.turtles then
    local cells, order = {}, {}
    for _, t in ipairs(d.turtles) do
      if t.x then
        local col, row = Map.toScreen(v, r, t.x, t.z)
        if Map.inside(r, col, row) then
          local k = col .. "," .. row
          if not cells[k] then
            cells[k] = { col = col, row = row, list = {} }
            order[#order + 1] = k
          end
          table.insert(cells[k].list, t)
        end
      end
    end
    for _, k in ipairs(order) do
      local c = cells[k]
      table.sort(c.list, function(a, b) return severity(a) > severity(b) end)
      local top = c.list[1]
      local glyph = #c.list > 1 and tostring(math.min(#c.list, 9)) or (top.h and G.heading[top.h] or G.noHeading)
      local selected = false
      local ids = {}
      for _, t in ipairs(c.list) do
        ids[#ids + 1] = t.id
        if t.id == self.sel then selected = true end
      end
      self.hits[k] = ids
      fb:set(c.col, c.row, glyph, selected and colors.black or self:turtleColor(top), selected and colors.white or colors.black)
      if not self.compact and #c.list == 1 then
        -- label to the right when the space is free
        local label = top.label or ("#" .. top.id)
        local room = r.x + r.w - c.col - 1
        local free = true
        for i = 1, math.min(#label, room) do
          local ch = fb:get(c.col + i, c.row)
          if ch ~= " " then free = false; break end
        end
        if free then fb:text(c.col + 1, c.row, label, colors.lightGray, nil, room) end
      end
    end
    -- selected turtle off-screen: arrow on the edge pointing at it
    local st = self.sel and self:turtle(self.sel)
    if st and st.x then
      local col, row = Map.toScreen(v, r, st.x, st.z)
      if not Map.inside(r, col, row) then
        local ec = U.clamp(col, r.x, r.x + r.w - 1)
        local er = U.clamp(row, r.y, r.y + r.h - 1)
        local g = col < r.x and G.left or (col >= r.x + r.w and G.right or (row < r.y and G.up or G.down))
        fb:set(ec, er, g, colors.black, colors.white)
      end
    end
  end

  fb:text(r.x + r.w - 2, r.y, "N" .. G.up, colors.lightGray, colors.black)
end

function App:dimText(d, full)
  local info = self.data.dims and self.data.dims[d]
  local label = full and P.dimLabel(d) or P.dimShort(d)
  if full and info and info.turtles > 0 then label = label .. " (" .. info.turtles .. ")" end
  return label
end

function App:drawWideBar(r)
  local fb, G = self.fb, self.G
  fb:fill(r.x, r.y, r.w, r.h, " ", colors.white, BAR_BG)
  local mid = r.y + math.floor((r.h - 1) / 2)
  local x = r.x
  local function btn(label, fn, on)
    x = self:button(x, r.y, #label + 2, r.h, label, fn, on and colors.white or colors.black, on and ON_BG or BTN_BG) + 1
  end
  local function txt(s, col)
    fb:text(x, mid, s, col or colors.white, BAR_BG)
    x = x + #s + 1
  end
  btn(G.left, function() self:cycleDim(-1) end)
  local dt = self:dimText(self.dim, true)
  local info = self.data.dims[self.dim]
  txt(U.pad(dt, 15), info and info.lost > 0 and colors.red or colors.yellow)
  btn(G.right, function() self:cycleDim(1) end)
  x = x + 1
  btn("-", function() Map.zoom(self:view(), 1) end)
  txt(U.pad(Map.scaleLabel(self:view()), 5))
  btn("+", function() Map.zoom(self:view(), -1) end)
  x = x + 1
  local v = self:view()
  local m = self.rects.map
  if r.w >= 66 then
    btn(G.left, function() Map.pan(v, -math.floor(m.w / 3), 0) end)
    btn(G.up, function() Map.pan(v, 0, -math.floor(m.h / 3)) end)
    btn(G.down, function() Map.pan(v, 0, math.floor(m.h / 3)) end)
    btn(G.right, function() Map.pan(v, math.floor(m.w / 3), 0) end)
    btn(G.center, function() self:centerOnFleet() end)
    x = x + 1
  end
  local long = r.w >= 110
  for _, l in ipairs({ { "T", "turtles", "Turtles" }, { "P", "players", "Players" },
    { "W", "waypoints", "Waypoints" }, { "M", "terrain", "Terrain" } }) do
    btn(long and l[3] or l[1], function()
      self.layers[l[2]] = not self.layers[l[2]]
      self:say(l[2] .. (self.layers[l[2]] and " shown" or " hidden"), 2)
    end, self.layers[l[2]])
  end
  local n = 0
  for _, a in ipairs(self.data.alerts) do if not a.acked then n = n + 1 end end
  local label = G.alert .. " " .. n
  local ax = r.x + r.w - #label - 2
  if ax > x then
    self:button(ax, r.y, #label + 2, r.h, label, function() self.sel = nil; self.panel = nil end,
      colors.white, n > 0 and colors.red or BTN_BG)
  end
end

function App:drawCompactBar(r)
  local fb, G = self.fb, self.G
  fb:fill(r.x, r.y, r.w, 1, " ", colors.white, BAR_BG)
  local x = r.x
  x = self:button(x, r.y, 1, 1, G.left, function() self:cycleDim(-1) end)
  local info = self.data.dims[self.dim]
  fb:text(x, r.y, self:dimText(self.dim, false), info and info.lost > 0 and colors.red or colors.yellow, BAR_BG)
  x = x + 3
  x = self:button(x, r.y, 1, 1, G.right, function() self:cycleDim(1) end) + 1
  x = self:button(x, r.y, 1, 1, "-", function() Map.zoom(self:view(), 1) end)
  local sl = Map.scaleLabel(self:view())
  fb:text(x, r.y, sl, colors.white, BAR_BG)
  x = x + #sl
  x = self:button(x, r.y, 1, 1, "+", function() Map.zoom(self:view(), -1) end) + 1
  x = self:button(x, r.y, 1, 1, G.menu, function() self.panel = self.panel ~= "menu" and "menu" or nil end,
    colors.black, self.panel == "menu" and colors.white or BTN_BG) + 1
  local n = 0
  for _, a in ipairs(self.data.alerts) do if not a.acked then n = n + 1 end end
  local label = G.alert .. n
  self:button(r.x + r.w - #label, r.y, #label, 1, label, function()
    self.panel = self.panel ~= "alerts" and "alerts" or nil
  end, colors.white, n > 0 and colors.red or BTN_BG)
end

function App:gpsSummary()
  local list = self.data.gps or {}
  local up = 0
  for _, g in ipairs(list) do if g.link ~= "lost" then up = up + 1 end end
  if #list == 0 then return "GPS: no hosts reporting", colors.orange end
  if up < 4 then return ("GPS: %d/%d up (need 4)"):format(up, #list), colors.red end
  if up < #list then return ("GPS: %d/%d up"):format(up, #list), colors.orange end
  return ("GPS: %d hosts OK"):format(up), colors.lime
end

function App:drawSide(r)
  local fb = self.fb
  fb:fill(r.x, r.y, r.w, r.h, " ", colors.white, PANEL_BG)
  for y = r.y, r.y + r.h - 1 do fb:set(r.x, y, "|", colors.gray) end
  local inner = { x = r.x + 2, y = r.y, w = r.w - 3, h = r.h }
  local t = self.sel and self:turtle(self.sel)
  if t then
    self:drawDetail(inner, t)
  elseif self.panel == "point" and self.target then
    self:drawPoint(inner)
  else
    local half = math.max(6, math.floor(inner.h * 0.55))
    self:drawList({ x = inner.x, y = inner.y, w = inner.w, h = half })
    self:drawAlerts({ x = inner.x, y = inner.y + half, w = inner.w, h = inner.h - half })
  end
end

function App:drawList(r)
  local fb, G, d = self.fb, self.G, self.data
  local y = r.y
  fb:text(r.x, y, ("TURTLES  %s  %d"):format(P.dimLabel(self.dim), #d.turtles), colors.yellow, nil, r.w)
  y = y + 1
  local gs, gc = self:gpsSummary()
  fb:text(r.x, y, gs, gc, nil, r.w)
  y = y + 1
  if #d.turtles == 0 then
    fb:text(r.x, y + 1, "No turtles in this dimension.", colors.lightGray, nil, r.w)
    return
  end
  local shown = 0
  for i, t in ipairs(d.turtles) do
    if y >= r.y + r.h - 1 and i < #d.turtles then
      fb:text(r.x, y, ("+%d more"):format(#d.turtles - shown), colors.gray, nil, r.w)
      break
    end
    local col = self:turtleColor(t)
    local status = t.link ~= "ok" and t.link:upper() or (t.status or "?")
    local name = ("#%d %s"):format(t.id, t.label or "")
    local rowW = r.w
    fb:text(r.x, y, t.h and G.heading[t.h] or G.noHeading, col)
    fb:text(r.x + 2, y, U.pad(name, rowW - #status - 3), colors.white)
    fb:text(r.x + rowW - #status, y, status, col)
    local id = t.id
    self.buttons[#self.buttons + 1] = { x1 = r.x, y1 = y, x2 = r.x + rowW - 1, y2 = y, fn = function() self:select(id) end }
    y = y + 1
    shown = shown + 1
  end
end

function App:drawAlerts(r)
  local fb, d = self.fb, self.data
  local y = r.y
  local alerts = d.alerts or {}
  fb:text(r.x, y, "ALERTS " .. #alerts, #alerts > 0 and colors.red or colors.yellow)
  if #alerts > 0 then
    self:button(r.x + r.w - 9, y, 9, 1, "ack all", function() self:act({ op = "ackAll" }) end)
  end
  y = y + 1
  if #alerts == 0 then
    fb:text(r.x, y + 1, "All good.", colors.lightGray, nil, r.w)
    return
  end
  for _, a in ipairs(alerts) do
    local lines = self:wrap(a.text, r.w - 2)
    if y + #lines > r.y + r.h then break end
    local col = a.acked and colors.gray or (SEV_COLOR[a.sev] or colors.white)
    for i, l in ipairs(lines) do
      fb:text(r.x, y, i == 1 and self.G.alert or " ", col)
      fb:text(r.x + 2, y, l, col)
      y = y + 1
    end
    local alert = a
    self.buttons[#self.buttons + 1] = {
      x1 = r.x, y1 = y - #lines, x2 = r.x + r.w - 1, y2 = y - 1,
      fn = function() self:openAlert(alert) end,
    }
  end
end

function App:openAlert(a)
  if not a.acked then self:act({ op = "ack", id = a.id }) end
  if a.dim and a.dim ~= self.dim then self:setDim(a.dim) end
  if a.tid and self:turtle(a.tid) then self:select(a.tid); self:centerOnSelected() end
end

function App:wrap(text, w)
  local lines = {}
  text = tostring(text)
  while #text > w do
    local cut = text:sub(1, w):match("^.*() ") or (w + 1)
    if cut <= 1 then cut = w + 1 end
    lines[#lines + 1] = text:sub(1, cut - 1)
    text = text:sub(cut):gsub("^ +", "")
  end
  lines[#lines + 1] = text
  return lines
end

function App:detailLines(t)
  local G = self.G
  local L = {}
  local function add(s, c) L[#L + 1] = { s, c or colors.white } end
  add(("#%d %s"):format(t.id, t.label or ""), colors.yellow)
  add(P.dimLabel(t.dim) .. "  facing " .. (t.h and P.HEADING_NAME[t.h] or "?"), colors.lightGray)
  add("Pos  " .. (t.x and U.fmtPos(t) or "unknown"), t.x and colors.white or colors.red)
  local fix = t.fix == "dr" and "dead reckoning" or (t.fix or "?")
  if t.fixAge then fix = fix .. ", gps " .. U.age(t.fixAge * 1000) .. " ago" end
  if t.fix == "none" and t.gpsErr then fix = "none: " .. t.gpsErr end
  add("Fix  " .. fix, t.fix == "none" and colors.red or colors.white)
  if t.fuel and t.fuel >= 0 then
    add(("Fuel %d / %d"):format(t.fuel, t.fuelMax or 0), t.lowFuel and colors.orange)
  else
    add("Fuel unlimited")
  end
  add(("Inv  %s / %s slots"):format(t.invUsed or "?", t.invTotal or "?"), t.full and colors.orange)
  add("Job  " .. (t.job or "-") .. (t.progress and (" " .. math.floor(t.progress * 100) .. "%") or ""))
  add("Stat " .. (t.status or "?"), self:turtleColor(t))
  local seen = "Seen " .. U.age(t.age) .. " ago"
  if t.link ~= "ok" then seen = seen .. "  " .. t.link:upper() end
  add(seen, t.link == "lost" and colors.red or (t.link == "stale" and colors.orange or colors.lightGray))
  if t.msg then add(t.msg, colors.orange) end
  if t.old then add("code " .. tostring(t.ver) .. " -> " .. tostring(self.data.ver), colors.cyan) end
  return L
end

function App:drawDetail(r, t)
  local fb = self.fb
  local y = r.y
  for _, l in ipairs(self:detailLines(t)) do
    for _, part in ipairs(self:wrap(l[1], r.w)) do
      if y >= r.y + r.h - 4 then break end
      fb:text(r.x, y, part, l[2], nil, r.w)
      y = y + 1
    end
  end
  if t.fuel and t.fuel >= 0 and t.fuelMax and t.fuelMax > 0 then
    local n = math.floor((r.w) * math.min(1, t.fuel / t.fuelMax) + 0.5)
    fb:fill(r.x, y, r.w, 1, " ", nil, colors.gray)
    fb:fill(r.x, y, n, 1, " ", nil, t.lowFuel and colors.orange or colors.green)
    y = y + 1
  end
  y = y + 1
  local bh = (self.rects.bar.h >= 3) and 3 or 1
  local x = r.x
  x = self:button(x, y, 8, bh, "Center", function() self:centerOnSelected() end) + 1
  x = self:button(x, y, 7, bh, "Close", function() self.sel = nil end) + 1
  if t.link ~= "ok" then
    local id = t.id
    self:button(x, y, 8, bh, "Forget", function() self.sel = nil; self:act({ op = "forget", id = id }) end,
      colors.white, colors.red)
  end
end

function App:drawPoint(r)
  local fb, t = self.fb, self.target
  fb:text(r.x, r.y, "MARKED POINT", colors.magenta)
  fb:text(r.x, r.y + 1, ("x %d   z %d"):format(t.x, t.z), colors.white)
  fb:text(r.x, r.y + 2, P.dimLabel(t.dim), colors.lightGray)
  local bh = (self.rects.bar.h >= 3) and 3 or 1
  local x = r.x
  x = self:button(x, r.y + 4, 13, bh, "Center here", function()
    self:centerOn(t.x, t.z); self.panel = nil
  end) + 1
  self:button(x, r.y + 4, 7, bh, "Clear", function() self.target = nil; self.panel = nil end)
  fb:text(r.x, r.y + 5 + bh, "Commands arrive in", colors.gray)
  fb:text(r.x, r.y + 6 + bh, "milestone 3.", colors.gray)
end

function App:sheet(r, lines)
  local top = math.max(r.y, r.y + r.h - lines)
  self.fb:fill(r.x, top, r.w, r.y + r.h - top, " ", colors.white, colors.black)
  self.fb:fill(r.x, top, r.w, 1, "\140", colors.gray, colors.black)
  return { x = r.x, y = top + 1, w = r.w, h = r.y + r.h - top - 1 }
end

function App:drawDetailSheet(r)
  local t = self:turtle(self.sel)
  local s = self:sheet(r, 12)
  local fb = self.fb
  local lines = self:detailLines(t)
  local y = s.y
  for i, l in ipairs(lines) do
    if y > s.y + s.h - 2 then break end
    if i ~= 2 then
      fb:text(s.x, y, l[1], l[2], nil, s.w)
      y = y + 1
    end
  end
  local by = s.y + s.h - 1
  local x = s.x
  x = self:button(x, by, 8, 1, "Center", function() self:centerOnSelected() end) + 1
  x = self:button(x, by, 7, 1, "Close", function() self.sel = nil end) + 1
  if t.link ~= "ok" then
    local id = t.id
    self:button(x, by, 8, 1, "Forget", function() self.sel = nil; self:act({ op = "forget", id = id }) end,
      colors.white, colors.red)
  end
end

function App:drawPointSheet(r)
  local s = self:sheet(r, 4)
  local t = self.target
  self.fb:text(s.x, s.y, ("Marked x %d  z %d"):format(t.x, t.z), colors.magenta, nil, s.w)
  local x = s.x
  x = self:button(x, s.y + 1, 13, 1, "Center here", function() self:centerOn(t.x, t.z); self.panel = nil end) + 1
  self:button(x, s.y + 1, 7, 1, "Clear", function() self.target = nil; self.panel = nil end)
end

function App:drawAlertsOverlay(r)
  local fb = self.fb
  fb:fill(r.x, r.y, r.w, r.h, " ", colors.white, colors.black)
  self:drawAlerts({ x = r.x, y = r.y, w = r.w, h = r.h })
end

function App:drawMenuOverlay(r)
  local fb = self.fb
  fb:fill(r.x, r.y, r.w, r.h, " ", colors.white, colors.black)
  local y = r.y
  fb:text(r.x, y, "LAYERS", colors.yellow)
  y = y + 1
  for _, l in ipairs({ { "Turtles", "turtles" }, { "Players", "players" }, { "Waypoints", "waypoints" }, { "Terrain", "terrain" } }) do
    local on = self.layers[l[2]]
    self:button(r.x, y, r.w, 1, (on and "[x] " or "[ ] ") .. l[1], function()
      self.layers[l[2]] = not self.layers[l[2]]
    end, on and colors.white or colors.lightGray, colors.black)
    y = y + 1
  end
  y = y + 1
  self:button(r.x, y, r.w, 1, "Center on fleet", function() self:centerOnFleet(); self.panel = nil end)
  y = y + 2
  self:drawList({ x = r.x, y = y, w = r.w, h = r.y + r.h - y })
end

function App:drawStatus(r)
  local fb, d = self.fb, self.data
  fb:fill(r.x, r.y, r.w, 1, " ", colors.lightGray, colors.black)
  local now = os.epoch("utc")
  local right
  local total, lost = 0, 0
  for _, info in pairs(d.dims or {}) do total, lost = total + info.turtles, lost + info.lost end
  if self.compact then
    local v = self:view()
    right = ("%d,%d"):format(math.floor(v.cx), math.floor(v.cz))
  else
    right = ("%d turtles%s  srv %s"):format(total, lost > 0 and (", " .. lost .. " lost") or "", d.ver or "?")
  end
  fb:text(r.x + r.w - #right, r.y, right, lost > 0 and colors.red or colors.gray)
  local left
  if self.toast and now < self.toastUntil then left = self.toast
  elseif self.compact then left = "drag: pan  tap: select"
  else left = "Tap a turtle for details, the map to mark a point" end
  fb:text(r.x, r.y, left, colors.white, nil, r.w - #right - 1)
end

-- Actions ---------------------------------------------------------------------------------

function App:centerOnSelected()
  local t = self.sel and self:turtle(self.sel)
  if t and t.x then self:centerOn(t.x, t.z) end
end

function App:centerOnFleet()
  local d = self.data
  local n, sx, sz = 0, 0, 0
  for _, t in ipairs(d.turtles) do
    if t.x then n, sx, sz = n + 1, sx + t.x, sz + t.z end
  end
  if n > 0 then
    self:centerOn(math.floor(sx / n), math.floor(sz / n))
  else
    for _, wp in ipairs(d.waypoints or {}) do
      if wp.kind == "garage" then self:centerOn(wp.x, wp.z) end
    end
  end
end

function App:tapMap(x, y)
  local r = self.rects.map
  local ids = self.hits[x .. "," .. y]
  if ids and #ids > 0 then
    -- tapping a stack of turtles cycles through them
    local nextId = ids[1]
    for i, id in ipairs(ids) do
      if id == self.sel then nextId = ids[i % #ids + 1] end
    end
    self:select(nextId)
    return
  end
  if self.sel or self.panel then
    self.sel, self.panel = nil, nil
    return
  end
  local wx, wz = Map.toWorld(self:view(), r, x, y)
  self.target = { x = wx, z = wz, dim = self.dim }
  self.panel = "point"
  self:say(("Marked %d, %d"):format(wx, wz))
end

function App:tap(x, y)
  local b = self:buttonAt(x, y)
  if b then
    b.fn()
    return true
  end
  local r = self.rects and self.rects.map
  if r and Map.inside(r, x, y) then
    self:tapMap(x, y)
    return true
  end
  return false
end

--- Feeds one event. Returns true when the screen should be redrawn.
function App:handle(ev, a, b, c)
  if ev == "monitor_touch" then
    if self.kind == "monitor" and a == self.side then return self:tap(b, c) end
    return false
  end
  if self.kind == "monitor" then return false end
  if ev == "mouse_click" then
    local btn = self:buttonAt(b, c)
    if btn then
      btn.fn()
      self.press = nil
      return true
    end
    self.press = { x = b, y = c, lx = b, ly = c, moved = false }
    return false
  elseif ev == "mouse_drag" and self.press then
    local dx, dy = b - self.press.lx, c - self.press.ly
    if dx ~= 0 or dy ~= 0 then
      Map.pan(self:view(), -dx, -dy)
      self.press.lx, self.press.ly, self.press.moved = b, c, true
      return true
    end
  elseif ev == "mouse_up" then
    local p = self.press
    self.press = nil
    if p and not p.moved then return self:tap(p.x, p.y) end
    return p ~= nil
  elseif ev == "mouse_scroll" then
    Map.zoom(self:view(), a)
    return true
  elseif ev == "key" then
    local v, m = self:view(), self.rects.map
    if a == keys.up then Map.pan(v, 0, -math.max(1, math.floor(m.h / 4)))
    elseif a == keys.down then Map.pan(v, 0, math.max(1, math.floor(m.h / 4)))
    elseif a == keys.left then Map.pan(v, -math.max(1, math.floor(m.w / 4)), 0)
    elseif a == keys.right then Map.pan(v, math.max(1, math.floor(m.w / 4)), 0)
    elseif a == keys.tab then self:cycleDim(1)
    elseif a == keys.backspace then self.sel, self.panel = nil, nil
    else return false end
    return true
  elseif ev == "char" then
    if a == "+" or a == "=" then Map.zoom(self:view(), -1)
    elseif a == "-" then Map.zoom(self:view(), 1)
    elseif a == "d" then self:cycleDim(1)
    elseif a == "t" then self.layers.turtles = not self.layers.turtles
    elseif a == "p" then self.layers.players = not self.layers.players
    elseif a == "w" then self.layers.waypoints = not self.layers.waypoints
    elseif a == "m" then self.layers.terrain = not self.layers.terrain
    elseif a == "c" then if self.sel then self:centerOnSelected() else self:centerOnFleet() end
    elseif a == "a" then self.panel = self.panel ~= "alerts" and "alerts" or nil
    else return false end
    return true
  end
  return false
end

--- Main loop: redraws on input and once a second.
function App:run()
  self:refresh()
  self:draw()
  local timer = os.startTimer(1)
  while true do
    local ev = table.pack(os.pullEvent())
    if ev[1] == "timer" and ev[2] == timer then
      self.blink = not self.blink
      self:refresh()
      self:draw()
      timer = os.startTimer(1)
    elseif ev[1] == "monitor_resize" or ev[1] == "term_resize" then
      self.fb:resize()
      self:draw()
    elseif self:handle(table.unpack(ev, 1, ev.n)) then
      self:refresh()
      self:draw()
    end
  end
end

return App
]=]
FILES["ui/fb.lua"] = [[
-- Frame buffer: draw a whole frame in memory, then blit only the rows that changed.
-- Avoids flicker on big monitors and keeps redraws cheap.

local FB = {}
FB.__index = FB

local HEX = {}
for i = 0, 15 do HEX[2 ^ i] = ("0123456789abcdef"):sub(i + 1, i + 1) end
FB.HEX = HEX

function FB.new(target)
  local self = setmetatable({ t = target, last = {} }, FB)
  self:resize()
  return self
end

function FB:resize()
  self.w, self.h = self.t.getSize()
  self.last = {}
  self:clear(colors.black)
end

function FB:clear(bg)
  local b = HEX[bg or colors.black]
  self.ch, self.fg, self.bg = {}, {}, {}
  for y = 1, self.h do
    local c, f, k = {}, {}, {}
    for x = 1, self.w do c[x], f[x], k[x] = " ", "0", b end
    self.ch[y], self.fg[y], self.bg[y] = c, f, k
  end
end

function FB:inside(x, y) return x >= 1 and y >= 1 and x <= self.w and y <= self.h end

--- fg/bg are color numbers; nil keeps what is there.
function FB:set(x, y, ch, fg, bg)
  if x < 1 or y < 1 or x > self.w or y > self.h then return end
  self.ch[y][x] = ch
  if fg then self.fg[y][x] = HEX[fg] end
  if bg then self.bg[y][x] = HEX[bg] end
end

function FB:get(x, y)
  if not self:inside(x, y) then return nil end
  return self.ch[y][x], self.fg[y][x], self.bg[y][x]
end

function FB:text(x, y, s, fg, bg, maxW)
  s = tostring(s)
  if maxW and #s > maxW then s = s:sub(1, maxW) end
  if y < 1 or y > self.h then return x + #s end
  local f, b = fg and HEX[fg], bg and HEX[bg]
  local cr, fr, br = self.ch[y], self.fg[y], self.bg[y]
  for i = 1, #s do
    local xx = x + i - 1
    if xx >= 1 and xx <= self.w then
      cr[xx] = s:sub(i, i)
      if f then fr[xx] = f end
      if b then br[xx] = b end
    end
  end
  return x + #s
end

function FB:fill(x, y, w, h, ch, fg, bg)
  local f, b = fg and HEX[fg], bg and HEX[bg]
  for yy = math.max(1, y), math.min(self.h, y + h - 1) do
    local cr, fr, br = self.ch[yy], self.fg[yy], self.bg[yy]
    for xx = math.max(1, x), math.min(self.w, x + w - 1) do
      cr[xx] = ch
      if f then fr[xx] = f end
      if b then br[xx] = b end
    end
  end
end

function FB:flush()
  local t = self.t
  for y = 1, self.h do
    local s, f, b = table.concat(self.ch[y]), table.concat(self.fg[y]), table.concat(self.bg[y])
    local key = s .. f .. b
    if self.last[y] ~= key then
      t.setCursorPos(1, y)
      t.blit(s, f, b)
      self.last[y] = key
    end
  end
end

return FB
]]
